INSERT INTO "public"."questions" ("id", "category", "question", "options", "correct_answer", "created_at", "slug", "updated_at", "explanation") VALUES
	('677bd1ee-c45c-4eb2-8fb4-c9137ae1ee24', 'Physiologie', 'In welchem Abschnitt des Tubulussystems befindet sich der Na-K-2Cl-Kotransporter NKCC2?', '["Dicker aufsteigender Teil der Henle-Schleife", "Proximaler Tubulus", "Distaler Tubulus", "Sammelrohr"]', 'Dicker aufsteigender Teil der Henle-Schleife', '2026-03-14 22:03:54.627029+00', 'physiologie-nkcc2-henle', '2026-03-14 22:18:29.584446+00', 'NKCC2 sitzt im dicken aufsteigenden Teil der Henle-Schleife. Dort werden Natrium, Kalium und Chlorid rueckresorbiert, und genau dort greifen auch Schleifendiuretika wie Furosemid an.'),
	('a0599730-3216-4516-8e0f-1b488f084956', 'Pathologie', 'Welche Nekroseform ist fuer einen ischaemischen Infarkt des Gehirns typisch?', '["Liquefaktionsnekrose", "Koagulationsnekrose", "Kaesenekrose", "Fibrinoide Nekrose"]', 'Liquefaktionsnekrose', '2026-03-14 22:03:54.627029+00', 'pathologie-hirninfarkt-liquefaktion', '2026-03-14 22:18:29.584446+00', 'Im Gehirn fuehrt Ischaemie typischerweise zu einer Liquefaktionsnekrose. Das liegt unter anderem am hohen Lipidgehalt und an hydrolytischen Enzymen, die das Gewebe verfluessigen.'),
	('03354f56-3dda-401f-9265-67825f118a95', 'Anatomie', 'In welche retroperitonealen Lymphknoten drainiert der Hoden primaer?', '["paraaortale (lumbale) Lymphknoten", "inguinale Lymphknoten", "Lymphknoten entlang der A. iliaca externa", "axillaere Lymphknoten"]', 'paraaortale (lumbale) Lymphknoten', '2026-03-14 22:03:54.627029+00', 'anatomie-testis-lymphabfluss', '2026-03-14 22:21:58.413641+00', 'Der Hoden drainiert zu paraaortalen Lymphknoten, weil seine embryologische Entwicklung im hinteren Abdomen beginnt. Deshalb folgt der Lymphabfluss nicht dem der skrotalen Haut.'),
	('141b9b53-f85f-4dae-a964-5b44da56cd9d', 'Physiologie', 'Welches Hormon foerdert im Sammelrohr ueber V2-Rezeptoren den Einbau von Aquaporin-2 in die apikale Membran?', '["ADH (Vasopressin)", "Aldosteron", "atriales natriuretisches Peptid (ANP)", "Renin"]', 'ADH (Vasopressin)', '2026-03-14 22:03:54.627029+00', 'physiologie-adh-aquaporin2', '2026-03-14 22:21:58.413641+00', 'ADH bindet an V2-Rezeptoren der Hauptzellen im Sammelrohr und foerdert den Einbau von Aquaporin-2. Dadurch steigt die Wasserrueckresorption und der Urin wird konzentrierter.'),
	('23177fb7-4bbb-4128-94e0-84f2e071960b', 'Physiologie', 'Welches Hormon senkt den Blutzuckerspiegel?', '["Insulin", "Glukagon", "Adrenalin", "Cortisol"]', 'Insulin', '2025-12-19 13:44:51.555638+00', 'physiologie-insulin', '2026-02-03 19:51:09.907698+00', 'Insulin wird in den Beta-Zellen des Pankreas gebildet. Es senkt den Blutzucker durch vermehrte Glukoseaufnahme und foerdert Glykogenspeicherung.'),
	('a0403a44-ea94-4e39-b818-63e6a9e5927a', 'Physiologie', 'Welchen Kanal reguliert Aldosteron besonders in den Hauptzellen des Sammelrohrs?', '["ENaC", "NKCC2", "CFTR", "GLUT4"]', 'ENaC', '2026-03-14 22:03:54.720926+00', 'physiologie-aldosteron-enaC', '2026-03-14 22:03:54.720926+00', 'Aldosteron steigert in den Hauptzellen die Expression und Aktivitaet des epithelialen Natriumkanals ENaC. Dadurch werden Natriumrueckresorption und Kaliumsekretion verstaerkt.'),
	('70bb3ce9-5060-4e8b-a57e-3f8b3efc8d95', 'Radiologie', 'Welche Bildgebung ist bei haemodynamisch stabilen Erwachsenen mit Verdacht auf Lungenembolie meist Standard?', '["CT-Angiographie der Pulmonalarterien", "MRT des Thorax", "Nativ-CT des Abdomens", "Roentgen der Hand"]', 'CT-Angiographie der Pulmonalarterien', '2026-03-14 22:03:54.627029+00', 'radiologie-pe-ctpa', '2026-03-14 22:18:29.584446+00', 'Bei stabiler Lungenembolieabklaerung ist die CT-Angiographie der Pulmonalarterien die Standardbildgebung. Sie zeigt intraluminale Fuellungsdefekte direkt in den Pulmonalarterien.'),
	('a05a999e-79a6-4f30-8b64-3cdc30d5768d', 'Chirurgie', 'Welche definitive Standardoperation wird bei symptomatischer Cholezystolithiasis durchgefuehrt?', '["Laparoskopische Cholezystektomie", "Appendektomie", "Hemikolektomie rechts", "Nierenteilresektion"]', 'Laparoskopische Cholezystektomie', '2026-03-14 22:03:54.627029+00', 'chirurgie-cholezystolithiasis-cholezystektomie', '2026-03-14 22:18:29.584446+00', 'Bei symptomatischen Gallensteinen ist die laparoskopische Cholezystektomie die definitive Therapie. Sie beseitigt die steintragende Gallenblase und senkt das Rezidivrisiko dauerhaft.'),
	('d8d4afb9-25a8-45a5-a6d2-74fa305c9f22', 'Radiologie', 'Welche Bildgebung ist in der Akutdiagnostik bei Verdacht auf frische Subarachnoidalblutung die erste Wahl?', '["kraniales Nativ-CT", "MRT der Hypophyse", "Abdomen-Sonographie", "Roentgen-Thorax"]', 'kraniales Nativ-CT', '2026-03-14 22:03:54.627029+00', 'radiologie-sah-nativ-ct', '2026-03-14 22:21:58.413641+00', 'Bei akuter Subarachnoidalblutung ist das kraniale Nativ-CT die schnellste und wichtigste Erstuntersuchung. Frisches Blut ist hier typischerweise gut sichtbar.'),
	('9a0ef141-91ee-4617-aa66-0b0f24be81cb', 'Chirurgie', 'Welche erste lebensrettende Massnahme ist bei klinischem Verdacht auf Spannungspneumothorax sofort erforderlich?', '["sofortige Nadeldekompression oder Entlastungspunktion", "Abwarten auf das Roentgenbild", "nur Analgesie", "Spirometrie"]', 'sofortige Nadeldekompression oder Entlastungspunktion', '2026-03-14 22:03:54.627029+00', 'chirurgie-spannungspneumothorax-entlastung', '2026-03-14 22:21:58.413641+00', 'Der Spannungspneumothorax ist eine akute Drucksituation und darf nicht erst bildgebend bestaetigt werden. Die sofortige Entlastungspunktion senkt den intrathorakalen Druck und stabilisiert Kreislauf und Atmung.'),
	('d881a973-17da-4e63-8ce0-537347c4b6a2', 'Anatomie', 'Wie viele Lungenlappen hat die rechte Lunge?', '["Zwei", "Drei", "Vier", "Fuenf"]', 'Drei', '2025-12-19 15:21:08.121842+00', 'anatomie-mittel-04', '2026-02-03 19:51:09.907698+00', 'Die rechte Lunge hat drei Lappen. Links sind es zwei Lappen, weil das Herz Raum einnimmt.'),
	('0eb5af7c-1ba8-46d4-abe1-b58929e60be6', 'Chirurgie', 'Wofuer spricht das Courvoisier-Zeichen aus schmerzlosem Ikterus und palpabel vergroesserter Gallenblase am ehesten?', '["Maligne distale Gallenwegsobstruktion", "Akute Virushepatitis", "Nierenkolik", "Duodenalulkus ohne Stauung"]', 'Maligne distale Gallenwegsobstruktion', '2026-03-14 22:03:54.720926+00', 'chirurgie-courvoisier-zeichen', '2026-03-14 22:14:57.440317+00', 'Das Courvoisier-Zeichen weist auf eine Abflussbehinderung der extrahepatischen Gallenwege hin, haeufig durch ein Pankreaskopfkarzinom oder distales Cholangiokarzinom. Die schmerzlos vergroesserte Gallenblase ist der entscheidende Hinweis.'),
	('deb9e52e-1041-4425-9fa6-f7e85f5043be', 'Biochemie', 'Welches Reduktionsaequivalent wird in der von G6PD katalysierten Reaktion des Pentosephosphatwegs direkt gebildet?', '["NADPH", "FADH2", "ATP", "Acetyl-CoA"]', 'NADPH', '2026-03-14 22:03:54.720926+00', 'biochemie-g6pd-nadph', '2026-03-14 22:18:29.584446+00', 'Die Glukose-6-Phosphat-Dehydrogenase erzeugt im Pentosephosphatweg NADPH. Dieses Reduktionsaequivalent ist entscheidend fuer antioxidativen Schutz, besonders in Erythrozyten.'),
	('8b624fca-e30d-4b0c-a9a4-991ad50b13fd', 'Genetik', 'Welche Robertson-Translokation ist klassisch mit einem Down-Syndrom assoziiert?', '["Translokation zwischen Chromosom 14 und 21", "Monosomie X", "Trisomie 13", "Deletion auf Chromosom 5p"]', 'Translokation zwischen Chromosom 14 und 21', '2026-03-14 22:03:54.720926+00', 'genetik-robertson-down-14-21', '2026-03-14 22:18:29.584446+00', 'Ein familiaeres Down-Syndrom kann durch eine Robertson-Translokation mit Beteiligung von Chromosom 21 entstehen, besonders rob(14;21). Genau diese Konstellation fuehrt zu zusaezlichem 21q-Material.'),
	('5db07fe9-f767-4168-a724-f12d0e236588', 'Genetik', 'Eine Mutation welches Gens ist typisch fuer das Marfan-Syndrom?', '["FBN1-Gen (Fibrillin-1)", "COL1A1-Gen", "DMD-Gen", "CFTR-Gen"]', 'FBN1-Gen (Fibrillin-1)', '2026-03-14 22:03:54.720926+00', 'genetik-marfan-fbn1', '2026-03-14 22:21:58.413641+00', 'Das Marfan-Syndrom beruht typischerweise auf Mutationen im FBN1-Gen, das fuer Fibrillin-1 kodiert. Dadurch entstehen die typischen Bindegewebsbefunde mit Aorten- und Skelettbeteiligung.'),
	('006bb5bc-dd34-4caf-bd48-da15d5a22210', 'Radiologie', 'Welcher Zielbefund soll mit der FAST-Sonographie im Schockraum primaer erkannt werden?', '["freie intraperitoneale oder perikardiale Fluessigkeit", "verminderte Knochendichte", "Herzzeitvolumen per MRT", "Hirnstammblutung"]', 'freie intraperitoneale oder perikardiale Fluessigkeit', '2026-03-14 22:03:54.720926+00', 'radiologie-fast-freie-fluessigkeit', '2026-03-14 22:21:58.413641+00', 'Die FAST-Untersuchung sucht schnell nach freier Fluessigkeit in Abdomen, Perikard und gegebenenfalls Thorax. Gerade dieser rasche Nachweis kann innere Blutungen frueh erkennbar machen.'),
	('943125e2-dc6b-43f0-95fb-b9cfb10d1967', 'Anatomie', 'Welche Kehlkopfmuskeln werden primaer vom N. laryngeus recurrens innerviert?', '["Fast alle inneren Kehlkopfmuskeln ausser dem M. cricothyroideus", "Nur der M. cricothyroideus", "Nur die suprahyalen Muskeln", "Die Schlundmuskulatur des Oesophagus"]', 'Fast alle inneren Kehlkopfmuskeln ausser dem M. cricothyroideus', '2026-03-14 22:12:26.645189+00', 'anatomie-nervus-laryngeus-recurrens', '2026-03-14 22:12:26.645189+00', 'Der N. laryngeus recurrens versorgt fast alle inneren Kehlkopfmuskeln motorisch. Die Ausnahme ist der M. cricothyroideus, der vom N. laryngeus superior innerviert wird.'),
	('6d3ad9d0-8025-41e0-96d1-6837858b1b9a', 'Physiologie', 'Welche Wirkung hat ADH ueber den V2-Rezeptor in den Hauptzellen des Sammelrohrs?', '["Einbau von Aquaporin-2 in die apikale Membran", "Hemmung der Harnstoffresorption", "Blockade von ENaC", "Verminderte Wasserpermeabilitaet"]', 'Einbau von Aquaporin-2 in die apikale Membran', '2026-03-14 22:12:26.645189+00', 'physiologie-adh-aquaporin-2', '2026-03-14 22:12:26.645189+00', 'ADH bindet an den V2-Rezeptor und fuehrt ueber cAMP zum Einbau von Aquaporin-2 in die apikale Membran. Dadurch steigt die Wasserpermeabilitaet des Sammelrohrs und der Urin wird konzentrierter.'),
	('57ca27f4-6a46-44d8-a2fb-3420a712d3dc', 'Physiologie', 'Welche Veraenderung des Milieus verschiebt die Sauerstoffbindungskurve des Haemoglobins ueber den Bohr-Effekt nach rechts?', '["Anstieg von CO2 und H+-Konzentration", "Abfall der Temperatur", "Abnahme von 2,3-BPG", "Alkalose"]', 'Anstieg von CO2 und H+-Konzentration', '2026-03-14 22:12:26.645189+00', 'physiologie-bohr-effekt', '2026-03-14 22:18:29.584446+00', 'Mehr CO2 und mehr Protonen senken die Sauerstoffaffinitaet des Haemoglobins und verschieben die Kurve nach rechts. Das erleichtert die O2-Abgabe im stoffwechselaktiven Gewebe.'),
	('5d7cdcb4-2bf8-4d2b-9636-05f587e3ab58', 'Pathologie', 'Welche Nekroseform entsteht typischerweise bei akutem ischaemischem Myokardinfarkt?', '["Koagulationsnekrose", "Verkaseungsnekrose", "Fettgewebsnekrose", "Fibrinoide Nekrose"]', 'Koagulationsnekrose', '2026-03-14 22:12:26.645189+00', 'pathologie-myokardinfarkt-koagulationsnekrose', '2026-03-14 22:18:29.584446+00', 'Beim ischaemischen Infarkt solider Organe wie Herz oder Niere entsteht typischerweise eine Koagulationsnekrose. Das passt direkt zur Ischaemiepathologie des akuten Myokardinfarkts.'),
	('5ae4ca73-cdd9-4cce-9c49-b06895b3de61', 'Anatomie', 'Welcher der folgenden Hirnnerven passiert nicht das Foramen jugulare?', '["N. hypoglossus (Hirnnerv XII)", "N. glossopharyngeus (Hirnnerv IX)", "N. vagus (Hirnnerv X)", "N. accessorius (Hirnnerv XI)"]', 'N. hypoglossus (Hirnnerv XII)', '2026-03-14 22:12:26.645189+00', 'anatomie-foramen-jugulare', '2026-03-14 22:21:58.413641+00', 'Durch das Foramen jugulare ziehen die Hirnnerven IX, X und XI. Der N. hypoglossus verlaeuft stattdessen durch den Canalis nervi hypoglossi.'),
	('6ffc5e1b-0232-4374-b8b4-8d128d6076ae', 'Anatomie', 'Welches Organ pumpt Blut durch den Koerper?', '["Leber", "Herz", "Lunge", "Niere"]', 'Herz', '2025-10-31 12:10:03.227174+00', 'leicht-1', '2026-03-14 13:27:23.944128+00', 'Das Herz ist die muskulaere Pumpe des Kreislaufs. Es befoerdert Blut sowohl durch den Lungen- als auch durch den Koerperkreislauf.'),
	('5a38d680-a882-443c-8883-8d33bc478421', 'Anatomie', 'Wie viele Lungenfluegel hat der Mensch?', '["Einen", "Zwei", "Drei", "Vier"]', 'Zwei', '2025-10-31 12:10:03.227174+00', 'leicht-2', '2026-03-14 13:27:23.944128+00', 'Der Mensch hat zwei Lungenfluegel, einen rechts und einen links. Rechts gibt es drei Lappen, links wegen des Herzens nur zwei.'),
	('7b030cd0-d7bf-472c-bf07-9785776932ad', 'Physiologie', 'Welcher Glukosetransporter wird durch Insulin vermehrt an die Zellmembran von Skelettmuskel- und Fettzellen gebracht?', '["GLUT4 in Muskel- und Fettzellen", "GLUT1", "SGLT1", "epithelialer Natriumkanal ENaC"]', 'GLUT4', '2026-03-14 22:12:26.645189+00', 'physiologie-glut4-insulin', '2026-03-14 22:21:58.413641+00', 'Insulin foerdert in Muskel- und Fettzellen die Translokation von GLUT4 an die Zellmembran. Genau dadurch steigt die Glukoseaufnahme in diese insulinempfindlichen Gewebe.'),
	('fe371384-9fa4-48ad-b483-d7464d850c76', 'Physiologie', 'Wie berechnet man das Herzzeitvolumen?', '["Schlagvolumen x Herzfrequenz", "Herzfrequenz / Schlagvolumen", "Blutdruck x Pulsdruck", "Atemfrequenz x Blutdruck"]', 'Schlagvolumen x Herzfrequenz', '2026-01-30 21:45:58.767708+00', 'physiologie-herz-02', '2026-01-30 21:45:58.767708+00', 'Herzzeitvolumen ist Schlagvolumen multipliziert mit der Herzfrequenz.'),
	('6e6fe657-a435-4a69-bd26-a1b78b8f08e1', 'Physiologie', 'Welches Hormon wird in der Niere gebildet und fördert die Erythropoese?', '["Erythropoetin", "Insulin", "Aldosteron", "ADH"]', 'Erythropoetin', '2026-01-30 21:45:58.767708+00', 'physiologie-niere-02', '2026-01-30 21:45:58.767708+00', 'Erythropoetin wird in der Niere gebildet und stimuliert die Erythropoese.'),
	('ccd22df0-503a-4d5e-b954-25c240521aa9', 'Pathologie', 'Welche metaplastische Veraenderung kennzeichnet den Barrett-Oesophagus?', '["Intestinale Metaplasie mit Becherzellen", "Plattenepithelhyperplasie ohne Zellwandel", "Verkalkung der Submukosa", "Dysplasie des Muskelgewebes"]', 'Intestinale Metaplasie mit Becherzellen', '2026-03-14 22:03:54.627029+00', 'pathologie-barrett-becherzellen', '2026-03-14 22:12:26.645189+00', 'Beim Barrett-Oesophagus wird das normale mehrschichtige Plattenepithel durch intestinal gepraegtes Zylinderepithel mit Becherzellen ersetzt. Diese Anpassung ist direkt mit chronischem Reflux verbunden und praekanzeroseverdachtig.'),
	('e08a4f71-c290-4991-bd63-5d09ae434299', 'Physiologie', 'Welches Protein wird hauptsächlich in der Leber gebildet und hält den kolloidosmotischen Druck?', '["Albumin", "Fibrinogen", "Immunglobulin", "Transferrin"]', 'Albumin', '2026-01-30 21:45:58.767708+00', 'physiologie-leber-01', '2026-01-30 21:45:58.767708+00', 'Albumin ist das wichtigste Plasmaprotein für den kolloidosmotischen Druck.'),
	('3e34b9fa-3010-467a-b8fd-abc3e67b85eb', 'Pathologie', 'Häufigste Ursache einer Subarachnoidalblutung?', '["Ruptur eines Aneurysmas", "Thrombose der A. carotis", "Sinusvenenthrombose", "Hirnabszess"]', 'Ruptur eines Aneurysmas', '2026-01-30 21:45:58.767708+00', 'pathologie-neuro-01', '2026-01-30 21:45:58.767708+00', 'Meistens entsteht die SAB durch Ruptur eines sakkulären Aneurysmas.'),
	('c0040340-3e7c-402f-93a8-38a6f474032f', 'Pathologie', 'Welches Emphysem-Muster in der Lunge ist fuer einen Alpha-1-Antitrypsin-Mangel typisch?', '["Panazinaeres Emphysem der Unterlappen", "Zentrolobulaeres Emphysem der Oberlappen", "Paraseptales Emphysem nur apikal", "Bullae ausschliesslich im Mittellappen"]', 'Panazinaeres Emphysem der Unterlappen', '2026-03-14 22:12:26.645189+00', 'pathologie-alpha1-antitrypsin-emphysem', '2026-03-14 22:14:57.440317+00', 'Beim Alpha-1-Antitrypsin-Mangel fehlt der Schutz vor elastasebedingtem Gewebeabbau. Deshalb entsteht typischerweise ein panazinaeres Emphysem, besonders in den Unterlappen.'),
	('3022c950-d4d4-4275-8880-4b4223ad1c86', 'Pathologie', 'Welcher histologische Leitbefund ist fuer eine rasch progrediente Glomerulonephritis typisch?', '["Halbmondbildungen in Bowman-Kapseln", "Mesangiale Amyloidablagerungen", "Ausschliesslich hyaline Arteriolosklerose", "Papillennekrosen im Nierenbecken"]', 'Halbmondbildungen in Bowman-Kapseln', '2026-03-14 22:12:26.645189+00', 'pathologie-rasch-progrediente-glomerulonephritis', '2026-03-14 22:18:29.584446+00', 'Bei der rasch progredienten Glomerulonephritis entstehen durch schwere glomerulaere Schaeden Halbmondbildungen aus proliferierenden Zellen und Fibrin in Bowman-Kapseln. Genau dieser Befund erklaert den schnellen Funktionsverlust.'),
	('d97bcfd0-c3fe-4f84-8178-2204d7a75c05', 'Pharmakologie', 'Welches Antidot neutralisiert unfraktioniertes Heparin in der Akutsituation am direktesten?', '["Protamin", "Vitamin K", "Idarucizumab", "Atropin"]', 'Protamin', '2026-03-14 22:12:26.645189+00', 'pharmakologie-heparin-protamin', '2026-03-14 22:18:29.584446+00', 'Protamin bindet an Heparin und neutralisiert dessen antikoagulatorische Wirkung. Genau deshalb wird es bei relevanter Blutung unter unfraktioniertem Heparin als Gegenmittel eingesetzt.'),
	('0e56356c-b547-4e06-8ad6-de1f0844e072', 'Pharmakologie', 'Welche gefuerchtete metabolische Komplikation erklaert die Vorsicht mit Metformin bei schwerer Niereninsuffizienz?', '["Laktatazidose", "Agranuzytose", "Rhabdomyolyse", "Aplastische Anaemie"]', 'Laktatazidose', '2026-03-14 22:12:26.645189+00', 'pharmakologie-metformin-laktatazidose', '2026-03-14 22:18:29.584446+00', 'Metformin kann sich bei schwer eingeschraenkter Nierenfunktion anreichern und das Risiko einer Laktatazidose erhoehen. Genau deshalb wird bei relevanter Niereninsuffizienz besondere Vorsicht oder ein Absetzen notwendig.'),
	('62cd7eee-23c9-46ac-a97f-594384716dda', 'Pathologie', 'Welcher Kernbefund ist fuer das papillaere Schilddruesenkarzinom klassisch?', '["Orphan-Annie-eye-Kerne", "Auerstaebchen", "Russell-Koerperchen", "Negri-Koerperchen"]', 'Orphan-Annie-eye-Kerne', '2026-03-14 22:12:26.645189+00', 'pathologie-papillaeres-schilddruesenkarzinom', '2026-03-14 22:21:58.413641+00', 'Das papillaere Schilddruesenkarzinom zeigt typische aufgehellte Kerne, die als Orphan-Annie-eye-Kerne beschrieben werden. Dieser Kernbefund verknuepft die Diagnose direkt mit diesem Tumortyp.'),
	('917f9946-ec71-47d5-9086-a131a46edc41', 'Pharmakologie', 'Welchen Tubulustransporter hemmen Schleifendiuretika im dicken aufsteigenden Teil der Henle-Schleife?', '["Na-K-2Cl-Kotransporter NKCC2", "epithelialer Natriumkanal ENaC", "Na+/K+-ATPase", "SGLT2"]', 'Na-K-2Cl-Kotransporter NKCC2', '2026-03-14 22:12:26.645189+00', 'pharmakologie-schleifendiuretika-nkcc2', '2026-03-14 22:21:58.413641+00', 'Schleifendiuretika blockieren den Na-K-2Cl-Kotransporter NKCC2 im dicken aufsteigenden Ast. Dadurch sinkt die Natriumrueckresorption stark und die Diurese steigt deutlich an.'),
	('7dd8057e-43dd-4824-904f-d22b1611c25f', 'Anatomie', 'Welcher Muskel initiiert beim Erwachsenen die ersten 0 bis 15 Grad der Armabduktion im Schultergelenk?', '["M. supraspinatus", "M. deltoideus", "M. infraspinatus", "M. subscapularis"]', 'M. supraspinatus', '2026-03-14 22:12:26.645189+00', 'anatomie-supraspinatus-abduktion', '2026-03-14 22:14:57.440317+00', 'Der M. supraspinatus startet die Armabduktion, bevor der M. deltoideus den groesseren Bewegungsanteil uebernimmt. Genau deshalb fuehrt eine Supraspinatuslaesion oft zum Problem beim Anheben des Arms aus der Nullstellung.'),
	('68684eb8-d126-4c96-b0e4-d64fdc45d2ce', 'Physiologie', 'Welche luminale Groesse registriert die Macula densa fuer das tubuloglomerulaere Feedback?', '["NaCl-Konzentration im distalen Tubulus", "Sauerstoffpartialdruck im Sammelrohr", "Albuminkonzentration in Bowman-Kapsel", "Kalziumspiegel im proximalen Tubulus"]', 'NaCl-Konzentration im distalen Tubulus', '2026-03-14 22:12:26.645189+00', 'physiologie-macula-densa-nacl', '2026-03-14 22:14:57.440317+00', 'Die Macula densa misst vor allem die Natriumchloridbeladung im distalen Tubulus. Ueber dieses Signal beeinflusst sie den Tonus der afferenten Arteriole und damit die glomerulaere Filtration.'),
	('c6e34845-49b4-48af-8f52-8aece056de6d', 'Physiologie', 'Welche Folge hat bei unveraenderter Kontraktilitaet eine erhoehte enddiastolische Fuellung auf das Schlagvolumen?', '["Mehr enddiastolische Fuellung erhoeht das Schlagvolumen", "Hoehere Herzfrequenz senkt das Schlagvolumen immer", "Verminderte Nachlast reduziert die Kontraktilitaet direkt", "Mehr Sympathikus senkt die Vorlast"]', 'Mehr enddiastolische Fuellung erhoeht das Schlagvolumen', '2026-03-14 22:12:26.645189+00', 'physiologie-frank-starling', '2026-03-14 22:14:57.440317+00', 'Beim Frank-Starling-Mechanismus fuehrt eine groessere enddiastolische Dehnung der Muskelfasern zu einer kraeftigeren Kontraktion. Genau deshalb steigt bei hoeherer Vorlast das Schlagvolumen.'),
	('17ec00af-a14f-4d9b-afd3-3e29f6eeae73', 'Physiologie', 'Wie veraendert Parathormon die renale Phosphatrueckresorption im proximalen Tubulus?', '["Die renale Phosphatrueckresorption nimmt ab", "Die renale Phosphatrueckresorption nimmt zu", "Die renale Phosphatrueckresorption bleibt unveraendert", "Die renale Phosphatrueckresorption steigt nur nachts"]', 'Sie nimmt ab', '2026-03-14 22:12:26.645189+00', 'physiologie-pth-phosphat', '2026-03-14 22:14:57.440317+00', 'Parathormon hemmt im proximalen Tubulus Natrium-Phosphat-Kotransporter. Dadurch sinkt die Phosphatrueckresorption und mehr Phosphat wird ausgeschieden.'),
	('c31e8663-58fc-43e0-bf58-1ecaf08a89d8', 'Physiologie', 'Welche Eigenschaft des fetalen Haemoglobins erklaert die Linksverschiebung seiner Sauerstoffbindungskurve gegenueber adultem Haemoglobin?', '["Geringere Bindung an 2,3-BPG", "Hoehere CO2-Bindung", "Staerkere Chloridbindung", "Verminderte H-Bindung an Globinketten"]', 'Geringere Bindung an 2,3-BPG', '2026-03-14 22:03:54.720926+00', 'physiologie-fetales-haemoglobin-links', '2026-03-14 22:14:57.440317+00', 'Fetales Haemoglobin bindet 2,3-BPG schlechter als adultes Haemoglobin. Dadurch hat es eine hoehere Sauerstoffaffinitaet und kann Sauerstoff aus dem muetterlichen Blut leichter aufnehmen.'),
	('3513ce96-8b8a-4cc8-bbc9-4db60f539236', 'Pathologie', 'Bei welcher Folgeerkrankung nach Streptokokkeninfektion finden sich klassisch Aschoff-Koerperchen im Herzen?', '["Akutes rheumatisches Fieber", "Amyloidose", "Sarkoidose", "Takayasu-Arteriitis"]', 'Akutes rheumatisches Fieber', '2026-03-14 22:03:54.720926+00', 'pathologie-aschoff-koerper', '2026-03-14 22:14:57.440317+00', 'Aschoff-Koerperchen sind granulomaehnliche Entzuendungsherde im Herzen bei akutem rheumatischem Fieber. Ihr Nachweis verknuepft die histologische Veraenderung direkt mit dieser poststreptokokkenbedingten Erkrankung.'),
	('b68e3a6a-3083-4f5f-b8b8-134da94f1020', 'Pharmakologie', 'Welche Substanz akkumuliert unter ACE-Hemmern und erklaert dadurch den trockenen Husten am besten?', '["Bradykinin", "Aldosteron", "Insulin", "Histamin"]', 'Bradykinin', '2026-03-14 22:03:54.720926+00', 'pharmakologie-ace-hemmer-bradykinin', '2026-03-14 22:14:57.440317+00', 'ACE baut normalerweise Bradykinin ab. Wird ACE gehemmt, steigt Bradykinin an und kann trockenen Husten sowie Angiooedeme beguenstigen.'),
	('ff95452b-44dd-456f-bf5f-7f8b48210b44', 'Pharmakologie', 'An welche bakterielle Ribosomenuntereinheit binden Aminoglykoside primaer?', '["30S-Untereinheit des Ribosoms", "50S-Untereinheit des Ribosoms", "DNA-Gyrase", "Dihydrofolatreduktase"]', '30S-Untereinheit des Ribosoms', '2026-03-14 22:03:54.720926+00', 'pharmakologie-aminoglykoside-30s', '2026-03-14 22:14:57.440317+00', 'Aminoglykoside binden an die 30S-Untereinheit bakterieller Ribosomen und stoeren die Proteinsynthese. Genau diese Bindung erklaert ihre bakterizide Wirkung gegen viele aerobe gramnegative Erreger.'),
	('4de513e1-5f8f-4226-9530-c6b69da52d19', 'Pharmakologie', 'An welche bakterielle Ribosomenuntereinheit binden Makrolide primaer?', '["50S-Untereinheit", "30S-Untereinheit", "DNA-Gyrase", "Peptidoglykan"]', '50S-Untereinheit', '2026-03-14 22:12:26.645189+00', 'pharmakologie-makrolide-50s', '2026-03-14 22:14:57.440317+00', 'Makrolide binden an die 50S-Untereinheit bakterieller Ribosomen und hemmen die Translokation. Genau diese Hemmung erklaert ihre Wirkung gegen viele atypische und grampositive Erreger.'),
	('196ce41c-8749-4ab4-9d02-ec511f1a08f5', 'Pharmakologie', 'Welcher pharmakologische Haupteffekt von Metformin senkt den Blutzucker bei Typ-2-Diabetes am staerksten?', '["Hemmung der hepatischen Glukoneogenese", "Stimulation der Beta-Zellsekretion", "Blockade des SGLT2 im proximalen Tubulus", "Aktivierung von PPAR-gamma"]', 'Hemmung der hepatischen Glukoneogenese', '2026-03-14 22:03:54.627029+00', 'pharmakologie-metformin-glukoneogenese', '2026-03-14 22:14:57.440317+00', 'Metformin senkt vor allem die hepatische Glukoseproduktion und verbessert damit die Stoffwechsellage bei Typ-2-Diabetes. Es wirkt nicht primaer durch direkte Insulinfreisetzung.'),
	('3ede9e2f-8192-4056-b080-d08e9add3356', 'Genetik', 'Wie viele Chromosomen hat der Mensch?', '["46", "44", "48", "52"]', '46', '2026-01-30 21:45:58.910706+00', 'genetik-extra-2026-01', '2026-03-14 13:27:24.246299+00', 'Der Mensch besitzt in somatischen Zellen 46 Chromosomen, also 23 Paare. Je ein Chromosom eines Paares stammt von jedem Elternteil.'),
	('77adcc05-be15-4b7f-b977-288bbd61474b', 'Physiologie', 'Welches Vitamin produziert der Koerper durch Sonnenlicht?', '["Vitamin A", "Vitamin B12", "Vitamin C", "Vitamin D"]', 'Vitamin D', '2025-10-31 12:10:03.227174+00', 'leicht-3', '2026-03-14 13:27:23.944128+00', 'Vitamin D wird in der Haut unter UV-B-Strahlung aus Vorstufen gebildet. Es ist wichtig fuer Kalziumhaushalt und Knochengesundheit.'),
	('162f034e-7cdc-4c65-a9b5-bf625bf0ac68', 'Anatomie', 'Welcher Blutbestandteil transportiert Sauerstoff?', '["Leukozyten", "Erythrozyten", "Thrombozyten", "Plasma"]', 'Erythrozyten', '2025-10-31 12:10:03.227174+00', 'leicht-4', '2026-03-14 13:27:23.944128+00', 'Erythrozyten transportieren Sauerstoff ueber ihr Haemoglobin. Dieses bindet O2 in der Lunge und gibt ihn im Gewebe wieder ab.'),
	('d04f75b9-161b-4994-a163-a8d9799fdd1a', 'Physiologie', 'Welche Koerpertemperatur gilt als Fieber?', '["Ab 37,0C", "Ab 37,5C", "Ab 38,0C", "Ab 39,0C"]', 'Ab 38,0C', '2025-10-31 12:10:03.227174+00', 'leicht-5', '2026-03-14 13:27:23.944128+00', 'Ab 38,0 C spricht man von Fieber. Ursache ist meist eine Sollwerterhoehung im Hypothalamus durch pyrogene Mediatoren.'),
	('1235d46a-b469-4b0b-844d-4817884e4dc0', 'Anatomie', 'Wie viele Zaehne hat ein erwachsener Mensch typischerweise?', '["28", "30", "32", "34"]', '32', '2025-10-31 12:10:03.227174+00', 'leicht-6', '2026-03-14 13:27:23.944128+00', 'Ein erwachsener Mensch hat typischerweise 32 Zaehne, wenn alle Weisheitszaehne vorhanden sind. Ohne Weisheitszaehne sind es oft weniger.'),
	('064504b2-0b40-4752-bded-c8242c509d84', 'Physiologie', 'Welche Blutgruppe gilt als Universalempfaenger?', '["0-", "A+", "B-", "AB+"]', 'AB+', '2025-10-31 12:10:03.227174+00', 'leicht-7', '2026-03-14 13:27:23.944128+00', 'AB+ gilt als Universalempfaenger fuer Erythrozyten, weil keine Anti-A- oder Anti-B-Antikoerper vorliegen und Rh-positives Blut vertragen wird.'),
	('5f613643-8c43-4a26-98df-7261239c6e98', 'Physiologie', 'Welches Mineral staerkt vor allem die Knochen?', '["Zink", "Kalzium", "Jod", "Eisen"]', 'Kalzium', '2025-10-31 12:10:03.227174+00', 'leicht-8', '2026-03-14 13:27:23.944128+00', 'Kalzium ist zentral fuer den Knochenaufbau und wird zusammen mit Phosphat in die Knochenmatrix eingebaut. Vitamin D erleichtert seine Aufnahme.'),
	('b4322daf-6966-4757-a731-ddaf1e3e0447', 'Anatomie', 'Wie viele Kammern hat das menschliche Herz?', '["Zwei", "Drei", "Vier", "Fuenf"]', 'Vier', '2025-10-31 12:10:03.227174+00', 'leicht-9', '2026-03-14 13:27:23.944128+00', 'Das menschliche Herz hat vier Kammern: zwei Vorhoefe und zwei Ventrikel. So bleiben Lungen- und Koerperkreislauf voneinander getrennt.'),
	('0ac2c52e-f8fd-4072-bb47-e32c72d04396', 'Anatomie', 'Welches Organ filtert das Blut und bildet Urin?', '["Milz", "Nieren", "Leber", "Magen"]', 'Nieren', '2025-10-31 12:10:03.227174+00', 'leicht-10', '2026-03-14 13:27:23.944128+00', 'Die Nieren filtern das Blut im Glomerulus und bilden daraus Primaerharn. Durch Rueckresorption und Sekretion entsteht schliesslich der Urin.'),
	('140dd797-9ed9-4c9d-b1ed-3c32806f9664', 'Anatomie', 'Wie viele Halswirbel besitzt der Mensch?', '["Fuenf", "Sieben", "Acht", "Zehn"]', 'Sieben', '2025-10-31 12:10:03.227174+00', 'leicht-11', '2026-03-14 13:27:23.944128+00', 'Der Mensch hat sieben Halswirbel von C1 bis C7. Sie tragen den Kopf und ermoeglichen die grosse Beweglichkeit der Halswirbelsaeule.'),
	('4d733e08-b606-4f23-9c38-8aa334514215', 'Anatomie', 'Welches Sinnesorgan ist hauptsaechlich fuer den Geruchssinn verantwortlich?', '["Zunge", "Auge", "Nase", "Ohr"]', 'Nase', '2025-10-31 12:10:03.227174+00', 'leicht-12', '2026-03-14 13:27:23.944128+00', 'Die Nase enthaelt das Riechepithel mit den Rezeptoren fuer Geruchsstoffe. Diese Signale werden ueber den N. olfactorius weitergeleitet.'),
	('eea49da6-73ad-4cf6-a57c-375b854c86bf', 'Anatomie', 'Welches Organ gehoert zum Verdauungssystem?', '["Lunge", "Leber", "Herz", "Milz"]', 'Leber', '2025-10-31 12:10:03.227174+00', 'leicht-14', '2026-03-14 13:27:23.944128+00', 'Die Leber gehoert zum Verdauungssystem, weil sie Galle produziert und Nahrungsbestandteile verstoffwechselt. Zusaetzlich uebernimmt sie Entgiftungs- und Speicherfunktionen.'),
	('10bba05c-5ad8-41a7-83be-d674e1b89fe3', 'Physiologie', 'Wie nennt man den fluessigen Anteil des Blutes?', '["Serum", "Plasma", "Lymphe", "Rheuma"]', 'Plasma', '2025-10-31 12:10:03.227174+00', 'leicht-15', '2026-03-14 13:27:23.944128+00', 'Plasma ist der fluessige Anteil des Blutes ohne Blutzellen. Es enthaelt Wasser, Elektrolyte, Proteine und Gerinnungsfaktoren.'),
	('0a5e4fbd-5fb0-4d39-8d60-60f5b94907a8', 'Physiologie', 'Welches Hormon reguliert den Blutzuckerspiegel?', '["Adrenalin", "Insulin", "Kortisol", "Thyroxin"]', 'Insulin', '2025-10-31 12:10:03.227174+00', 'mittel-1', '2026-03-14 13:27:23.944128+00', 'Insulin ist das zentrale blutzuckersenkende Hormon. Es foerdert die Aufnahme von Glukose in Zellen und die Speicherung als Glykogen.'),
	('8ecf8e00-7879-4e04-8f05-9d5e8864a54c', 'Anatomie', 'Welche Struktur verbindet Muskel mit Knochen?', '["Baender", "Sehnen", "Knorpel", "Faszien"]', 'Sehnen', '2025-10-31 12:10:03.227174+00', 'mittel-2', '2026-03-14 13:27:23.944128+00', 'Sehnen verbinden Muskel mit Knochen und uebertragen die Muskelkraft auf das Skelett. Baender verbinden dagegen Knochen mit Knochen.'),
	('cb1850da-40e5-467d-9f21-a33fcd688895', 'Physiologie', 'Welcher Teil des Gehirns steuert das Gleichgewicht?', '["Grosshirn", "Kleinhirn", "Zwischenhirn", "Hirnstamm"]', 'Kleinhirn', '2025-10-31 12:10:03.227174+00', 'mittel-3', '2026-03-14 13:27:23.944128+00', 'Das Kleinhirn koordiniert Gleichgewicht, Haltung und fein abgestimmte Bewegungen. Schaedigungen fuehren zu Ataxie und Dysmetrie.'),
	('1ce0f9ec-8f85-43e7-87b9-f3aefdb100d6', 'Pharmakologie', 'Welcher Gerinnungsfaktor ist Vitamin-K-abhaengig?', '["Faktor II", "Faktor VIII", "Faktor IX", "Faktor XII"]', 'Faktor II', '2025-10-31 12:10:03.227174+00', 'mittel-4', '2026-03-14 13:27:23.944128+00', 'Faktor II, also Prothrombin, gehoert zu den Vitamin-K-abhaengigen Gerinnungsfaktoren. Ebenfalls dazu zaehlen VII, IX und X sowie Protein C und S.'),
	('b3b806ee-9385-4d6d-980b-138f82fb2866', 'Physiologie', 'Welches Organ produziert Insulin?', '["Milz", "Leber", "Pankreas", "Niere"]', 'Pankreas', '2025-10-31 12:10:03.227174+00', 'mittel-6', '2026-03-14 13:27:23.944128+00', 'Das Pankreas produziert Insulin in seinen Beta-Zellen. Das Hormon senkt den Blutzucker und ist fuer den Glukosestoffwechsel zentral.'),
	('9db04cc8-1157-4846-81fa-5edcf7e877af', 'Physiologie', 'Welche Struktur sorgt fuer die Filtration im Nephron?', '["Bowman-Kapsel", "Henle-Schleife", "Distaler Tubulus", "Sammelrohr"]', 'Bowman-Kapsel', '2025-10-31 12:10:03.227174+00', 'mittel-7', '2026-03-14 13:27:23.944128+00', 'Die Filtration findet im Nierenkoerperchen statt, also im Glomerulus mit Bowman-Kapsel. Dort wird aus Blutplasma der Primaerharn gebildet.'),
	('7cf4c61b-674d-422f-b29d-681de0ffa4a8', 'Immunologie', 'Welche Zellen produzieren Antikoerper?', '["T-Lymphozyten", "B-Lymphozyten", "Makrophagen", "Neutrophile"]', 'B-Lymphozyten', '2025-10-31 12:10:03.227174+00', 'mittel-8', '2026-03-14 13:27:23.944128+00', 'Antikoerper werden letztlich von Plasmazellen gebildet, die aus aktivierten B-Lymphozyten hervorgehen. In einfachen Fragen wird deshalb oft die B-Lymphozyten-Linie als Ursprung gesucht.'),
	('124d566c-b4b7-42ab-b2d2-470f76167dfe', 'Physiologie', 'Welches Vitamin ist wichtig fuer die Blutgerinnung?', '["Vitamin K", "Vitamin B1", "Vitamin D", "Vitamin E"]', 'Vitamin K', '2025-10-31 12:10:03.227174+00', 'mittel-9', '2026-03-14 13:27:23.944128+00', 'Vitamin K ist noetig fuer die Gamma-Carboxylierung mehrerer Gerinnungsfaktoren. Ohne diesen Schritt koennen die Faktoren Calcium schlechter binden und weniger wirksam arbeiten.'),
	('f77b8ee9-2759-4bbe-9bae-c281784b39d5', 'Anatomie', 'Welcher Nerv steuert die mimische Muskulatur?', '["N. trigeminus", "N. facialis", "N. glossopharyngeus", "N. vagus"]', 'N. facialis', '2025-10-31 12:10:03.227174+00', 'mittel-10', '2026-03-14 13:27:23.944128+00', 'Der N. facialis innerviert die mimische Muskulatur motorisch. Eine Laesion fuehrt typischerweise zu einer Fazialisparese.'),
	('67803333-7060-4371-99f6-61013e18bf3d', 'Pharmakologie', 'Welches Medikament wird zur Behandlung einer bakteriellen Pneumonie eingesetzt?', '["Penicillin", "Paracetamol", "Metformin", "Omeprazol"]', 'Penicillin', '2025-10-31 12:10:03.227174+00', 'mittel-11', '2026-03-14 13:27:23.944128+00', 'Penicillin wirkt gegen viele empfindliche bakterielle Erreger, zum Beispiel Pneumokokken. Ob es geeignet ist, haengt aber immer vom vermuteten Erreger und Resistenzmuster ab.'),
	('bb3b61ca-c851-4b82-8927-3dd4040b0e9d', 'Anatomie', 'Wie viele Wirbel besitzt die Brustwirbelsaeule?', '["10", "12", "14", "16"]', '12', '2025-10-31 12:10:03.227174+00', 'mittel-13', '2026-03-14 13:27:23.944128+00', 'Die Brustwirbelsaeule besteht aus 12 Wirbeln, bezeichnet als Th1 bis Th12. An ihnen artikulieren auch die Rippen.'),
	('89168fb1-8a71-44b1-9dc3-9f2d20bc5dec', 'Physiologie', 'Welches Ion ist hauptsaechlich fuer das Aktionspotenzial der Muskelzelle verantwortlich?', '["Kalium", "Kalzium", "Chlorid", "Natrium"]', 'Natrium', '2025-10-31 12:10:03.227174+00', 'mittel-14', '2026-03-14 13:27:23.944128+00', 'Der schnelle Aufstrich des Aktionspotenzials in Muskel- und Nervenzellen beruht vor allem auf Natriumeinstrom. Kalium ist dagegen wichtig fuer die Repolarisation.'),
	('8d0d441e-869c-4138-99de-d34fc202fb8f', 'Biochemie', 'Welches Enzym ist fuer die Spaltung von Staerke im Mund verantwortlich?', '["Pepsin", "Lipase", "Amylase", "Trypsin"]', 'Amylase', '2025-10-31 12:10:03.227174+00', 'mittel-15', '2026-03-14 13:27:23.944128+00', 'Die Amylase im Speichel beginnt bereits im Mund mit der Spaltung von Staerke zu kleineren Kohlenhydraten. Deshalb startet die Verdauung von Kohlenhydraten schon vor dem Magen.'),
	('08864ba0-f4c8-4eb1-8c28-9592a8fe636e', 'Genetik', 'Welche Mutation ist typisch fuer Mukoviszidose?', '["F508del im CFTR-Gen", "HTT-CAG-Repeat", "KRAS G12D", "JAK2 V617F"]', 'F508del im CFTR-Gen', '2025-10-31 12:10:03.227174+00', 'schwer-4', '2026-03-14 13:27:23.944128+00', 'Die haeufigste Mutation bei Mukoviszidose ist F508del im CFTR-Gen. Dadurch wird der Chloridkanal fehlgefaltet und es entsteht zaehes Sekret.'),
	('9f81e5e8-4bae-415e-b4a7-fdb2a3ffbf2d', 'Immunologie', 'Welche AutoantikKoerper sind typisch fuer Morbus Basedow?', '["Anti-CCP", "TRAK", "ANA", "Anti-TPO"]', 'TRAK', '2025-10-31 12:10:03.227174+00', 'schwer-6', '2026-03-14 13:27:23.944128+00', 'TRAK sind Antikoerper gegen den TSH-Rezeptor und typisch fuer Morbus Basedow. Sie stimulieren die Schilddruese und verursachen die Hyperthyreose.'),
	('2752462e-2242-485d-9d3a-fc6fdb1fd229', 'Genetik', 'Welche genetische Veraenderung ist charakteristisch fuer CML?', '["JAK2 V617F", "BCR-ABL", "KRAS", "EGFR"]', 'BCR-ABL', '2025-10-31 12:10:03.227174+00', 'schwer-9', '2026-03-14 13:27:23.944128+00', 'BCR-ABL entsteht durch die Translokation t(9;22), das Philadelphia-Chromosom. Das Fusionsprotein wirkt als dauerhaft aktive Tyrosinkinase und ist typisch fuer CML.'),
	('7cc921ed-ba7a-4262-aa0c-c4da6c0f700c', 'Immunologie', 'Welcher AutoantikKoerper ist typisch fuer eine autoimmune Hepatitis Typ 1?', '["ANA", "AMA", "ANCA", "Anti-Jo-1"]', 'ANA', '2025-10-31 12:10:03.227174+00', 'schwer-11', '2026-03-14 13:27:23.944128+00', 'ANA sind haeufig bei Autoimmunhepatitis Typ 1 nachweisbar. Daneben koennen auch SMA auftreten, waehrend LKM-1 eher fuer Typ 2 spricht.'),
	('14b91c56-2a8e-4cab-91ab-c9d75f5c160c', 'Pharmakologie', 'Welches Antibiotikum deckt Pseudomonas aeruginosa typischerweise ab?', '["Amoxicillin", "Ciprofloxacin", "Clarithromycin", "Cefazolin"]', 'Ciprofloxacin', '2025-10-31 12:10:03.227174+00', 'schwer-14', '2026-03-14 13:27:23.944128+00', 'Ciprofloxacin deckt Pseudomonas aeruginosa als eines der wenigen oral verfuegbaren Antibiotika typischerweise ab. Die konkrete Therapie richtet sich aber immer nach Fokus und Resistenzlage.'),
	('7023e80e-261e-4aa3-af87-260fe7c9e2cf', 'Pharmakologie', 'Welcher Elektrolyt muss vor einer Amiodaron-Gabe korrigiert werden?', '["Natrium", "Magnesium", "Kalium", "Kalzium"]', 'Kalium', '2025-10-31 12:10:03.227174+00', 'schwer-15', '2026-03-14 13:27:23.944128+00', 'Vor Amiodaron sollte insbesondere Kalium im Normbereich liegen, weil Hypokaliaemie proarrhythmisch wirkt und das Risiko fuer QT-vermittelte Rhythmusstoerungen erhoeht.'),
	('adc81000-d480-4831-aab3-fa32b05a36d7', 'Pharmakologie', 'Welches Medikament wird häufig als Erstlinientherapie bei bakteriellen Infektionen eingesetzt?', '["Ibuprofen", "Amoxicillin", "Metformin", "Lisinopril"]', 'Amoxicillin', '2025-10-31 12:03:26.617031+00', 'cc0e6a8c78b4ef8d09496b8e3ece20ca', '2026-03-14 13:27:23.944128+00', 'Amoxicillin ist ein haeufig eingesetztes Beta-Laktam-Antibiotikum fuer viele bakterielle Infektionen. Es hemmt die bakterielle Zellwandsynthese.'),
	('7a38e058-d818-48a0-a43d-826573abc0f1', 'Pathologie', 'Welche Zellart ist typisch erhöht bei einer allergischen Reaktion?', '["Neutrophile", "Eosinophile", "Lymphozyten", "Makrophagen"]', 'Eosinophile', '2025-10-31 12:03:26.617031+00', 'a729d83fa47c8f50bec2a67376efab03', '2026-03-14 13:27:23.944128+00', 'Eosinophile sind bei allergischen Reaktionen und parasitaeren Erkrankungen haeufig erhoeht. Sie enthalten Granula mit toxischen Proteinen und Entzuendungsmediatoren.'),
	('2e2bac3d-77d3-4a03-83f8-7e4dcbab1f31', 'Mikrobiologie', 'Welcher Erreger verursacht Tuberkulose?', '["Staphylococcus aureus", "Mycobacterium tuberculosis", "Escherichia coli", "Streptococcus pneumoniae"]', 'Mycobacterium tuberculosis', '2025-10-31 12:03:26.617031+00', 'ff8723d35dd026a3c5f5f700c4a1612a', '2026-03-14 13:27:23.944128+00', 'Mycobacterium tuberculosis ist der klassische Erreger der Tuberkulose. Das saeurefeste Stabchen wird meist aerogen uebertragen und befaellt vor allem die Lunge.'),
	('af24d655-5c46-430c-a731-73a2bb791dd7', 'Anatomie', 'Welche Struktur trennt die thorakale von der abdominalen Höhle?', '["Diaphragma", "Peritoneum", "Mediastinum", "Pleura"]', 'Diaphragma', '2025-10-31 12:03:26.617031+00', 'a85a3df16daf010f74680b5784e6a88d', '2026-03-14 13:27:23.944128+00', 'Das Diaphragma beziehungsweise Zwerchfell trennt Brust- und Bauchhoehle. Gleichzeitig ist es der wichtigste Atemmuskel.'),
	('8dfe4c58-0b0e-4e3f-8f87-8321a672a0d0', 'Physiologie', 'Welcher Mechanismus beschreibt den Transport von Sauerstoff im Blut?', '["Diffusion", "Aktiver Transport", "Erleichterte Diffusion durch Hämoglobin", "Osmose"]', 'Erleichterte Diffusion durch Hämoglobin', '2025-10-31 12:03:26.617031+00', '0d7baf735110d06a97bf1e8b69768a77', '2026-03-14 13:27:23.944128+00', 'Sauerstoff wird im Blut vor allem ueber die Bindung an Haemoglobin transportiert. So kann wesentlich mehr O2 mitgefuehrt werden als nur in geloester Form.'),
	('808d66ce-f0ec-43a2-985e-68b84e83e645', 'Pharmakologie', 'Welcher Wirkmechanismus gehört zu Protonenpumpenhemmern wie Omeprazol?', '["Hemmung der H+/K+-ATPase", "Blockade von H2-Rezeptoren", "COX-2-Inhibition", "Stimulation der Protonenpumpe"]', 'Hemmung der H+/K+-ATPase', '2025-10-31 12:03:26.617031+00', '15342c2813de192a8da9dd6463bc4ab7', '2026-03-14 13:27:23.944128+00', 'Protonenpumpenhemmer wie Omeprazol hemmen die H+/K+-ATPase der Belegzellen irreversibel. Dadurch sinkt die Magensaeureproduktion deutlich.'),
	('adbbeeca-5b58-406b-bebb-8345238869f4', 'Anatomie', 'Welcher Score bewertet die Schwere einer ambulanten Pneumonie?', '["CHA2DS2-VASc", "CRB-65", "APGAR", "SOFA"]', 'CRB-65', '2025-10-31 12:10:03.227174+00', 'schwer-7', '2026-03-14 13:27:23.944128+00', 'CRB-65 bewertet Confusion, Respiratory rate, Blood pressure und Alter ab 65 Jahren. Der Score hilft, das Risiko einer ambulant erworbenen Pneumonie einzuschaetzen.'),
	('aeb6d4fc-4a85-44df-8507-92c3b1cc6023', 'Pathologie', 'Welche Veränderung ist kennzeichnend für eine chronische Entzündung?', '["Fibrinexsudat", "Mononukleäre Infiltration", "Nekrose pur", "Akkute Ödembildung"]', 'Mononukleäre Infiltration', '2025-10-31 12:03:26.617031+00', '0711ce6c8d266ceb9966b08ff5c1dd2e', '2026-03-14 13:27:23.944128+00', 'Chronische Entzuendung ist durch mononukleaere Zellen wie Makrophagen, Lymphozyten und Plasmazellen gekennzeichnet. Oft kommen Gewebszerstoerung und Reparaturprozesse hinzu.'),
	('dc249bc3-e9a7-49c9-be17-d1b9e8b34e8a', 'Mikrobiologie', 'Welcher Virustyp besitzt ein einzelsträngiges RNA-Genom und verursacht häufig Erkältungen?', '["Adenovirus", "Rhinovirus", "Herpesvirus", "Papillomavirus"]', 'Rhinovirus', '2025-10-31 12:03:26.617031+00', '6fe7e16001d97ba62942102fbf896b00', '2026-03-14 13:27:23.944128+00', 'Rhinoviren sind unbehuelte, einzelstraengige RNA-Viren und der haeufigste Ausloeser der gewoehnlichen Erkaeltung. Sie vermehren sich besonders gut in den oberen Atemwegen.'),
	('2e54e344-c92e-4272-9b52-e082112448ce', 'Anatomie', 'Welche Arterie versorgt primär den lateralen Teil des Hirnhemisphärenkortex?', '["A. carotis interna", "A. cerebri media", "A. cerebri posterior", "A. basilaris"]', 'A. cerebri media', '2025-10-31 12:03:26.617031+00', '88f79f192028b8afd3b7c6c3f8d0e23c', '2026-03-14 13:27:23.944128+00', 'Die A. cerebri media versorgt grosse Teile des lateralen Frontal-, Parietal- und Temporallappens. Ein Verschluss fuehrt haeufig zu Sprach- und Motorikdefiziten.'),
	('f0c216c8-e81e-4592-983e-3627d508b58c', 'Physiologie', 'Welcher Signalweg ist zentral für die Regulation des Zellwachstums und wird häufig bei Krebs verändert?', '["Wnt/β-Catenin", "GABAergic", "Renin-Angiotensin", "Notch nicht beteiligt"]', 'Wnt/β-Catenin', '2025-10-31 12:03:26.617031+00', '477efe8985a76ec28a28138b180111d9', '2026-03-14 13:27:23.944128+00', 'Der Wnt/beta-Catenin-Signalweg reguliert Proliferation, Differenzierung und Zellschicksal. Fehlregulationen foerdern unkontrolliertes Wachstum und spielen bei vielen Tumoren eine Rolle.'),
	('46352f08-b275-4f03-8b8d-3d776225febb', 'Pharmakologie', 'Welcher Mechanismus steht hinter der Wirkung von Statinen?', '["Hemmung der HMG-CoA-Reduktase", "Blockade der LDL-Rezeptoren", "Erhöhung der Cholesterinaufnahme", "Inhibition der Lipase"]', 'Hemmung der HMG-CoA-Reduktase', '2025-10-31 12:03:26.617031+00', '04d5a7ef0124cf304c904996a945df8d', '2026-03-14 13:27:23.944128+00', 'Statine hemmen die HMG-CoA-Reduktase, das Schluesselenzym der Cholesterinsynthese. Dadurch sinkt vor allem das LDL-Cholesterin.'),
	('25149828-c90c-4083-af04-394ad9c90462', 'Pathologie', 'Welche Onkogenmutation ist klassisch mit malignen Melanomen assoziiert?', '["KRAS", "BRAF V600E", "TP53", "BRCA1"]', 'BRAF V600E', '2025-10-31 12:03:26.617031+00', '86430368402cda51e337a319513d61d3', '2026-03-14 13:27:23.944128+00', 'BRAF V600E aktiviert die MAP-Kinase-Signalkaskade dauerhaft und findet sich haeufig bei malignen Melanomen. Die Mutation ist therapeutisch relevant, weil es gezielte BRAF-Inhibitoren gibt.'),
	('768875f2-2eae-4f35-9e89-a05f93efe075', 'Genetik', 'Welcher Score dient der Risikostratifikation beim Vorhofflimmern?', '["CHA2DS2-VASc", "HAS-BLED", "APGAR", "SOFA"]', 'CHA2DS2-VASc', '2025-10-31 12:10:03.227174+00', 'schwer-5', '2026-03-14 13:27:23.944128+00', 'Der CHA2DS2-VASc-Score schaetzt das Schlaganfallrisiko bei Vorhofflimmern ab. Er hilft bei der Entscheidung, ob eine orale Antikoagulation noetig ist.'),
	('d7006bf2-6425-4c85-9551-5bdb661838b4', 'Physiologie', 'Welcher Test dient zur Diagnose einer pernizioesen Anaemie?', '["Schilling-Test", "H2-Atemtest", "Coombs-Test", "Mantoux-Test"]', 'Schilling-Test', '2025-10-31 12:10:03.227174+00', 'schwer-1', '2026-03-14 13:27:23.944128+00', 'Der Schilling-Test pruefte historisch die Vitamin-B12-Aufnahme und half so bei der Diagnose einer pernizioesen Anaemie durch Intrinsic-Factor-Mangel. Heute wird er nur noch selten verwendet.'),
	('2fbe5b85-6902-4444-a594-f30881c6bd6f', 'Pathologie', 'Welcher Tumormarker spricht fuer ein Ovarialkarzinom?', '["CA 15-3", "AFP", "CA 19-9", "CA 125"]', 'CA 125', '2025-10-31 12:10:03.227174+00', 'schwer-10', '2026-03-14 13:27:23.944128+00', 'CA 125 ist ein Tumormarker, der bei Ovarialkarzinomen oft erhoeht ist. Er eignet sich eher zur Verlaufskontrolle als zum Screening.'),
	('5f956926-91ef-4222-833b-1b0c5b077ee9', 'Biochemie', 'Welches Antidot wird bei Paracetamol-Ueberdosierung eingesetzt?', '["Naloxon", "Flumazenil", "Acetylcystein", "Protamin"]', 'Acetylcystein', '2025-10-31 12:10:03.227174+00', 'schwer-8', '2026-03-14 13:27:23.944128+00', 'Acetylcystein fuellt die Glutathionspeicher wieder auf und entgiftet den toxischen Paracetamol-Metaboliten NAPQI. Es ist besonders wirksam, wenn es frueh gegeben wird.'),
	('a628bbbd-4e35-49d1-a9b0-7f00b6e519df', 'Mikrobiologie', 'Welcher Pilz bildet verzweigte, filamentoese Hyphen und verursacht opportunistische Infektionen?', '["Candida albicans", "Aspergillus fumigatus", "Mycobacterium leprae", "Clostridium difficile"]', 'Aspergillus fumigatus', '2025-10-31 12:03:26.617031+00', 'cf61219aed42d992b729f1fdd951329d', '2026-03-14 13:27:23.944128+00', 'Aspergillus fumigatus ist kein Bakterium, sondern ein Schimmelpilz. Er verursacht vor allem bei immunsupprimierten Personen opportunistische Infektionen wie die invasive Aspergillose.'),
	('98b893b2-6c21-489a-a575-c9d6401f061b', 'Chirurgie', 'Welches inhalative Medikament wird initial beim Status asthmaticus bevorzugt?', '["Ipratropium", "Schnell wirksames Beta-2-Spray", "Theophyllin i.v.", "Adrenalin i.m."]', 'Schnell wirksames Beta-2-Spray', '2025-10-31 12:10:03.227174+00', 'schwer-12', '2026-03-14 13:27:23.944128+00', 'Schnell wirksame Beta-2-Agonisten sind die wichtigste initiale Bronchodilatation beim Status asthmaticus. Sie werden hoch dosiert inhalativ oder vernebelt gegeben und haeufig mit weiteren Eskalationsmassnahmen kombiniert.'),
	('949e89c3-5e63-4c01-bd3e-22e659a6988e', 'Radiologie', 'Welches Antikoagulans wird initial bei akuter Lungenembolie mit Schock bevorzugt?', '["Niedermolekulares Heparin", "Unfraktioniertes Heparin", "Fondaparinux", "NOAK"]', 'Unfraktioniertes Heparin', '2025-10-31 12:10:03.227174+00', 'schwer-3', '2026-03-14 13:27:23.944128+00', 'Unfraktioniertes Heparin wird bei massiver Lungenembolie mit Schock initial bevorzugt, weil es sofort wirkt und bei instabilen Patientinnen und Patienten gut steuerbar ist. Parallel muss eine rasche Reperfusionsstrategie geprueft werden.'),
	('9a7f1d33-dc34-49c6-b315-d60149fd8973', 'Anatomie', 'Welches Organ produziert Insulin?', '["Leber", "Bauchspeicheldrüse", "Milz", "Niere"]', 'Bauchspeicheldrüse', '2025-10-27 21:06:40.505273+00', '274e59afa67a65701b70b0f622d84d32', '2026-03-14 13:27:23.944128+00', 'Die Bauchspeicheldruese produziert Insulin in den Beta-Zellen der Langerhans-Inseln. Das Hormon senkt den Blutzucker, indem es die Glukoseaufnahme in Gewebe foerdert.'),
	('24b9e368-5ada-4225-b7f8-54405aebdc0d', 'Pharmakologie', 'Was ist ein Beta-Blocker?', '["Antibiotikum", "Antihypertensivum", "Diuretikum", "Vasodilatator"]', 'Antihypertensivum', '2025-10-27 21:06:40.505273+00', '95decb43077f9b1729f7bcbb18156619', '2026-03-14 13:27:23.944128+00', 'Beta-Blocker blockieren beta-adrenerge Rezeptoren und senken dadurch Herzfrequenz, Kontraktilitaet und Blutdruck. Sie werden unter anderem bei Hypertonie und tachykarden Rhythmusstoerungen eingesetzt.'),
	('fff09c95-24d3-4995-afda-6fc40d188d03', 'Anatomie', 'Welcher Knochen bildet das vordere Ende des Thorax und verbindet die Rippenpaare?', '["Sternum", "Clavicula", "Scapula", "Humerus"]', 'Sternum', '2025-10-31 12:03:26.617031+00', '6d70b123daf1cd31bf73e4abe7e49dbe', '2026-03-14 13:27:23.944128+00', 'Das Sternum bildet die Vorderwand des Thorax. Ueber Knorpelverbindungen sind dort die meisten Rippenpaare befestigt.'),
	('b2bdaf3e-a7d6-4067-9f3d-cd4e44869afb', 'Physiologie', 'Welches Organ ist primär für die Produktion von Insulin verantwortlich?', '["Leber", "Bauchspeicheldrüse", "Milz", "Niere"]', 'Bauchspeicheldrüse', '2025-10-31 12:03:26.617031+00', 'f4f93696564acb52bfa4c9f60e9b4b93', '2026-03-14 13:27:23.944128+00', 'Die Bauchspeicheldruese produziert Insulin in ihren Beta-Zellen. Das Hormon senkt den Blutzucker und ist zentral fuer den Glukosestoffwechsel.'),
	('8c37b29d-53d4-466a-8830-5e9409e46373', 'Anatomie', 'Wie heisst der Knochen des Unterarms auf der Daumenseite?', '["Radius", "Ulna", "Humerus", "Fibula"]', 'Radius', '2026-01-30 21:45:58.910706+00', 'anatomie-extra-2026-01', '2026-03-14 13:27:24.246299+00', 'Der Radius liegt in anatomischer Grundstellung auf der Daumenseite des Unterarms. Die Ulna liegt dagegen auf der Kleinfingerseite.'),
	('d716bcb6-9316-4556-a885-3e20b506a9bf', 'Anatomie', 'Welche Struktur verläuft durch den Canalis carpi?', '["N. medianus", "N. ulnaris", "N. radialis", "N. musculocutaneus"]', 'N. medianus', '2026-01-30 21:45:58.910706+00', 'anatomie-extra-2026-02', '2026-03-14 13:27:24.246299+00', 'Durch den Canalis carpi ziehen der N. medianus und mehrere Beugesehnen. Wird der Nerv dort eingeengt, entsteht das typische Karpaltunnelsyndrom.'),
	('53dcc16d-99c0-45c7-ac73-675491654184', 'Pharmakologie', 'Welcher Wirkstoff ist ein direkter Faktor-Xa-Hemmer?', '["Rivaroxaban", "Warfarin", "Heparin", "Dabigatran"]', 'Rivaroxaban', '2025-12-19 15:21:08.121842+00', 'pharmakologie-mittel-04', '2026-02-03 19:51:09.907698+00', 'Rivaroxaban hemmt Faktor Xa direkt und oral. Es benoetigt keine routinemaessige INR-Kontrolle wie Warfarin.'),
	('ebe49eb0-734e-424a-8271-51d82359c7d8', 'Pharmakologie', 'Welcher Wirkstoff ist ein SSRI?', '["Sertralin", "Amitriptylin", "Venlafaxin", "Haloperidol"]', 'Sertralin', '2025-12-19 15:21:08.121842+00', 'pharmakologie-mittel-05', '2026-02-03 19:51:09.907698+00', 'Sertralin ist ein SSRI und erhoeht Serotonin im synaptischen Spalt. Es wird bei Depression, Angst und Zwangsstoerungen eingesetzt.'),
	('45762fe6-e5e6-48c6-806c-3fd8f35b3a27', 'Pharmakologie', 'Welches Antidot wird bei Paracetamol-Intoxikation gegeben?', '["N-Acetylcystein", "Flumazenil", "Naloxon", "Atropin"]', 'N-Acetylcystein', '2025-12-19 15:21:08.121842+00', 'pharmakologie-schwer-01', '2026-02-03 19:51:09.907698+00', 'N-Acetylcystein fuellt Glutathion auf und entgiftet das toxische NAPQI. Es ist das Standardantidot bei Paracetamol-Ueberdosierung und wirkt am besten frueh.'),
	('43e0a3d9-1ef4-486a-a62a-1d1a8a1b8922', 'Anatomie', 'Welche Arterie versorgt die Milz?', '["A. splenica", "A. hepatica", "A. renalis", "A. mesenterica inferior"]', 'A. splenica', '2026-01-30 21:45:58.910706+00', 'anatomie-extra-2026-03', '2026-03-14 13:27:24.246299+00', 'Die A. splenica entspringt aus dem Truncus coeliacus und zieht entlang des Pankreas zur Milz. Sie ist die arterielle Hauptversorgung der Milz.'),
	('da985737-a75e-4877-9b54-589b998542d3', 'Physiologie', 'Welches Hormon erhöht die Herzfrequenz akut?', '["Adrenalin", "Insulin", "Cortisol", "Prolaktin"]', 'Adrenalin', '2026-01-30 21:45:58.910706+00', 'physiologie-extra-2026-01', '2026-03-14 13:27:24.246299+00', 'Adrenalin aktiviert am Herzen vor allem Beta-1-Rezeptoren. Dadurch steigen Herzfrequenz und Kontraktilitaet innerhalb kurzer Zeit an.'),
	('2d67e8f7-5d65-42b3-a354-93b3b020fda4', 'Physiologie', 'Wo wird ADH gespeichert und freigesetzt?', '["Neurohypophyse", "Adenohypophyse", "Nebennierenrinde", "Schilddrüse"]', 'Neurohypophyse', '2026-01-30 21:45:58.910706+00', 'physiologie-extra-2026-02', '2026-03-14 13:27:24.246299+00', 'ADH wird im Hypothalamus gebildet, aber in der Neurohypophyse gespeichert und von dort freigesetzt. Genau nach diesem Speicher- und Freisetzungsort fragt die Aufgabe.'),
	('b59913c1-62c1-40b9-9538-2a0a4a123f99', 'Physiologie', 'Welcher Transporter ist für Glukoseaufnahme in Muskel insulinabhängig?', '["GLUT4", "GLUT1", "GLUT2", "SGLT1"]', 'GLUT4', '2026-01-30 21:45:58.910706+00', 'physiologie-extra-2026-03', '2026-03-14 13:27:24.246299+00', 'GLUT4 ist der insulinabhaengige Glukosetransporter in Muskel- und Fettzellen. Nach Insulinwirkung wird er in die Zellmembran eingebaut und steigert dort die Glukoseaufnahme.'),
	('6d7668c9-7cbc-4bc3-81db-26845ed38cc8', 'Pathologie', 'Wie nennt man eine Entzündung der Bauchspeicheldrüse?', '["Pankreatitis", "Hepatitis", "Appendizitis", "Gastritis"]', 'Pankreatitis', '2026-01-30 21:45:58.910706+00', 'pathologie-extra-2026-01', '2026-03-14 13:27:24.246299+00', 'Die Endung -itis bezeichnet eine Entzuendung. Zusammen mit Pankreas ergibt sich deshalb Pankreatitis als korrekter Fachbegriff.'),
	('e62554d8-4aa8-4773-bedf-ba209f4c3155', 'Pathologie', 'Welche Nekroseform ist typisch beim Hirninfarkt?', '["Kolliquationsnekrose", "Koagulationsnekrose", "Fettgewebsnekrose", "Fibrinoidnekrose"]', 'Kolliquationsnekrose', '2026-01-30 21:45:58.910706+00', 'pathologie-extra-2026-02', '2026-03-14 13:27:24.246299+00', 'Im Gehirn entsteht nach einem Infarkt typischerweise eine Kolliquationsnekrose. Das Gewebe wird enzymatisch verfluessigt, statt seine Architektur wie bei der Koagulationsnekrose zu behalten.'),
	('14005380-03c2-4df1-9389-a5eb2664f4db', 'Pathologie', 'Welche Mutation ist typisch beim Li-Fraumeni-Syndrom?', '["p53", "BRCA1", "APC", "RB1"]', 'p53', '2026-01-30 21:45:58.910706+00', 'pathologie-extra-2026-03', '2026-03-14 13:27:24.246299+00', 'Das Li-Fraumeni-Syndrom beruht meist auf Keimbahnmutationen in TP53. Faellt p53 aus, gehen wichtige Kontrollen von DNA-Schaeden und Zellzyklus verloren.'),
	('4768832f-7e99-4deb-8a83-dc52156f644e', 'Pharmakologie', 'Welcher Wirkstoff ist ein ACE-Hemmer?', '["Enalapril", "Amlodipin", "Bisoprolol", "Furosemid"]', 'Enalapril', '2026-01-30 21:45:58.910706+00', 'pharmakologie-extra-2026-01', '2026-03-14 13:27:24.246299+00', 'Enalapril gehoert an der Endung -pril zur Gruppe der ACE-Hemmer. Diese blockieren die Umwandlung von Angiotensin I in Angiotensin II.'),
	('bdfeed5e-3343-487b-8e7d-411954b1ee6b', 'Pharmakologie', 'Welches Antibiotikum hemmt die bakterielle Proteinsynthese an der 30S-Untereinheit?', '["Doxycyclin", "Erythromycin", "Vancomycin", "Ceftriaxon"]', 'Doxycyclin', '2026-01-30 21:45:58.910706+00', 'pharmakologie-extra-2026-02', '2026-03-14 13:27:24.246299+00', 'Doxycyclin ist ein Tetracyclin und bindet an die 30S-Untereinheit bakterieller Ribosomen. Dadurch wird die Proteinsynthese gehemmt.'),
	('d891ebb6-df24-4e7c-b8a4-e6cc24bf7140', 'Pharmakologie', 'Welches Antidot wird bei Heparin-Überdosierung gegeben?', '["Protamin", "Naloxon", "Flumazenil", "Vitamin K"]', 'Protamin', '2026-01-30 21:45:58.910706+00', 'pharmakologie-extra-2026-03', '2026-03-14 13:27:24.246299+00', 'Protamin ist stark positiv geladen und bindet dadurch das negativ geladene Heparin. So wird die antikoagulatorische Wirkung rasch neutralisiert.'),
	('dd1d76f4-3b44-4b1f-a9a5-9002e5814739', 'Mikrobiologie', 'Welcher Erreger verursacht typischerweise Scharlach?', '["Streptococcus pyogenes", "Staphylococcus aureus", "Haemophilus influenzae", "Neisseria meningitidis"]', 'Streptococcus pyogenes', '2026-01-30 21:45:58.910706+00', 'mikrobiologie-extra-2026-01', '2026-03-14 13:27:24.246299+00', 'Scharlach wird durch toxinbildende Staemme von Streptococcus pyogenes verursacht. Das erythrogene Toxin erklaert Exanthem und Himbeerzunge.'),
	('7f723e0e-7418-445d-b828-16a17d06b6a0', 'Mikrobiologie', 'Welcher Erreger ist obligat intrazellulär?', '["Chlamydia trachomatis", "Escherichia coli", "Staphylococcus aureus", "Pseudomonas aeruginosa"]', 'Chlamydia trachomatis', '2026-01-30 21:45:58.910706+00', 'mikrobiologie-extra-2026-02', '2026-03-14 13:27:24.246299+00', 'Chlamydia trachomatis ist obligat intrazellulaer, weil der Erreger fuer seinen Stoffwechsel auf die Wirtszelle angewiesen ist. Deshalb kann er sich nicht frei ausserhalb von Zellen vermehren.'),
	('9b52a4fc-5571-43cf-9097-48b513f45910', 'Mikrobiologie', 'Welches Toxin verursacht Pseudomembranen bei Diphtherie?', '["Diphtherietoxin", "Tetanustoxin", "Botulinumtoxin", "Exotoxin A"]', 'Diphtherietoxin', '2026-01-30 21:45:58.910706+00', 'mikrobiologie-extra-2026-03', '2026-03-14 13:27:24.246299+00', 'Das Diphtherietoxin hemmt den Elongationsfaktor 2 und stoppt so die Proteinsynthese. Lokal fuehrt das zu Nekrosen und den typischen Pseudomembranen.'),
	('4bf12282-1e93-476f-90c2-64432f730e33', 'Biochemie', 'Welche Reaktion katalysiert die ATP-Synthase?', '["ADP + Pi -> ATP", "ATP -> ADP + Pi", "Glukose -> Pyruvat", "Pyruvat -> Laktat"]', 'ADP + Pi -> ATP', '2026-01-30 21:45:58.910706+00', 'biochemie-extra-2026-01', '2026-03-14 13:27:24.246299+00', 'Die ATP-Synthase nutzt den Protonengradienten der inneren Mitochondrienmembran, um ADP und anorganisches Phosphat zu ATP zusammenzufuegen. Genau diese Reaktion katalysiert sie.'),
	('addfc16e-a0aa-4b00-adcd-1ef7f669b06e', 'Biochemie', 'Welcher Zyklus oxidiert Acetyl-CoA?', '["Citratzyklus", "Harnstoffzyklus", "Glykolyse", "Pentosephosphatweg"]', 'Citratzyklus', '2026-01-30 21:45:58.910706+00', 'biochemie-extra-2026-02', '2026-03-14 13:27:24.246299+00', 'Der Citratzyklus oxidiert Acetyl-CoA zu CO2 und liefert dabei NADH und FADH2 fuer die Atmungskette. Deshalb ist er das zentrale oxidative Stoffwechselrad.'),
	('5240cf6b-86ff-4a98-9ccf-b7ad83ba3f88', 'Biochemie', 'Welches Molekül ist Endprodukt der Glykolyse?', '["Pyruvat", "Laktat", "Acetyl-CoA", "Oxalacetat"]', 'Pyruvat', '2026-01-30 21:45:58.910706+00', 'biochemie-extra-2026-03', '2026-03-14 13:27:24.246299+00', 'Die Glykolyse endet mit Pyruvat. Laktat entsteht erst anschliessend aus Pyruvat, wenn der Stoffwechsel auf anaerobe Bedingungen ausweicht.'),
	('95f627e0-64de-40a7-b758-872a81bae043', 'Pathologie', 'Welche Entzuendung betrifft den Blinddarm?', '["Appendizitis", "Cholezystitis", "Pankreatitis", "Gastritis"]', 'Appendizitis', '2025-12-19 15:21:08.121842+00', 'pathologie-leicht-02', '2026-02-03 19:51:09.907698+00', 'Appendizitis ist die Entzuendung des Appendix vermiformis, oft durch Lumeneinengung oder Kotstein. Unbehandelt kann sie perforieren.'),
	('11ebf331-4492-4607-9a51-c5fb03d66422', 'Immunologie', 'Welche Zellen präsentieren Antigen über MHC II?', '["Dendritische Zellen", "Erythrozyten", "Thrombozyten", "Neurone"]', 'Dendritische Zellen', '2026-01-30 21:45:58.910706+00', 'immunologie-extra-2026-01', '2026-03-14 13:27:24.246299+00', 'Dendritische Zellen sind professionelle antigenpraesentierende Zellen. Sie praesentieren Peptide ueber MHC II und aktivieren dadurch naive CD4-T-Zellen.'),
	('6f39bac3-747c-4c2a-9299-7d2e74306708', 'Immunologie', 'Welche Zellen vermitteln zytotoxische Abwehr?', '["CD8 T-Zellen", "B-Zellen", "Neutrophile", "Makrophagen"]', 'CD8 T-Zellen', '2026-01-30 21:45:58.910706+00', 'immunologie-extra-2026-02', '2026-03-14 13:27:24.246299+00', 'CD8-T-Zellen erkennen Antigene ueber MHC I und toeten infizierte oder entartete Zellen. Damit tragen sie die klassische zytotoxische Abwehr.'),
	('86b49522-4c45-4f87-8960-9eb4c5584224', 'Immunologie', 'Welches Zytokin ist zentral für die Th1-Antwort?', '["IFN-gamma", "IL-4", "IL-10", "TGF-beta"]', 'IFN-gamma', '2026-01-30 21:45:58.910706+00', 'immunologie-extra-2026-03', '2026-03-14 13:27:24.246299+00', 'IFN-gamma aktiviert Makrophagen und foerdert die zellulaere Immunantwort. Deshalb ist es ein Schluesselzytokin der Th1-Antwort.'),
	('475570da-a756-4514-8540-3bd9aabe065c', 'Genetik', 'Wie nennt man das Fehlen eines Chromosoms?', '["Monosomie", "Trisomie", "Deletion", "Duplikation"]', 'Monosomie', '2026-01-30 21:45:58.910706+00', 'genetik-extra-2026-02', '2026-03-14 13:27:24.246299+00', 'Bei einer Monosomie fehlt ein Chromosom aus einem normalen Paar. Im Gegensatz dazu liegt bei einer Trisomie eines zu viel vor.'),
	('fe8d20ad-9041-4668-b650-eed38c55cf97', 'Genetik', 'Welche Mutation führt zur Sichelzellanämie?', '["Glu->Val in beta-Globin", "Trinukleotid-Expansion", "Frameshift in BRCA1", "Deletion von Exon 7"]', 'Glu->Val in beta-Globin', '2026-01-30 21:45:58.910706+00', 'genetik-extra-2026-03', '2026-03-14 13:27:24.246299+00', 'Die Sichelzellanamie entsteht klassisch durch einen Austausch von Glutamat gegen Valin im Beta-Globin. Dadurch polymerisiert desoxygeniertes HbS leichter und verformt Erythrozyten sichelfoermig.'),
	('b94149ff-4da5-4df5-a31b-4317537a7cff', 'Radiologie', 'Welche Bildgebung ist erste Wahl bei Verdacht auf Fraktur?', '["Röntgen", "CT", "MRI", "Ultraschall"]', 'Röntgen', '2026-01-30 21:45:58.910706+00', 'radiologie-extra-2026-01', '2026-03-14 13:27:24.246299+00', 'Roentgen ist bei Frakturverdacht meist die erste Wahl, weil es schnell verfuegbar, guenstig und sehr gut fuer die Beurteilung knoecherner Strukturen geeignet ist.'),
	('0abccbf9-4dc2-4f8b-9c29-1ed73be316d8', 'Radiologie', 'Welches Kontrastmittel wird beim CT häufig verwendet?', '["Iodhaltiges Kontrastmittel", "Gadolinium", "Barium für MRI", "Luft"]', 'Iodhaltiges Kontrastmittel', '2026-01-30 21:45:58.910706+00', 'radiologie-extra-2026-02', '2026-03-14 13:27:24.246299+00', 'Beim CT werden meist iodhaltige Kontrastmittel verwendet, weil Iod als Element mit hoher Ordnungszahl Roentgenstrahlen stark abschwaecht. Dadurch heben sich Gefaesse und gut durchblutete Gewebe im CT deutlich besser ab.'),
	('4dd7693d-c8bf-45ff-b04c-b1e58ea5d6a0', 'Radiologie', 'Welche MRT-Sequenz zeigt Fett hell?', '["T1", "T2", "STIR", "DWI"]', 'T1', '2026-01-30 21:45:58.910706+00', 'radiologie-extra-2026-03', '2026-03-14 13:27:24.246299+00', 'In T1-Sequenzen erscheint Fett hell, weil es eine kurze T1-Relaxationszeit hat. Fluessigkeit ist in T1 dagegen eher dunkel und in T2 signalreicher.'),
	('12e2fcdc-2be1-4a02-af91-6c7cb056e50d', 'Chirurgie', 'Wie nennt man das Entfernen des Blinddarms?', '["Appendektomie", "Cholezystektomie", "Gastrektomie", "Nephrektomie"]', 'Appendektomie', '2026-01-30 21:45:58.910706+00', 'chirurgie-extra-2026-01', '2026-03-14 13:27:24.246299+00', 'Die Endung -ektomie bedeutet operative Entfernung. Bei einer Appendektomie wird also der Appendix vermiformis entfernt.'),
	('c3a4fe23-2cda-412b-9fa4-f2e63882f795', 'Anatomie', 'Welche Kammer pumpt Blut in den Lungenkreislauf?', '["Rechter Ventrikel", "Linker Ventrikel", "Rechter Vorhof", "Linker Vorhof"]', 'Rechter Ventrikel', '2025-12-19 13:44:51.555638+00', 'anatomie-lungenkreislauf', '2026-02-03 19:51:09.907698+00', 'Der rechte Ventrikel pumpt Blut ueber die A. pulmonalis in den Lungenkreislauf. Dort wird es oxygeniert und gelangt ueber die Lungenvenen in den linken Vorhof.'),
	('fc47340d-7439-488d-95a0-48f3c4899d6e', 'Pharmakologie', 'Welcher Wirkstoff ist ein Vitamin-K-Antagonist?', '["Warfarin", "Heparin", "Dabigatran", "Rivaroxaban"]', 'Warfarin', '2025-12-19 13:44:51.555638+00', 'pharmakologie-vitamin-k-antagonist', '2026-02-03 19:51:09.907698+00', 'Warfarin hemmt die Vitamin-K-Epoxid-Reduktase und reduziert die Aktivierung der Faktoren II, VII, IX und X. Die Wirkung setzt verzoegert ein und erfordert INR-Kontrolle.'),
	('1afc5335-552c-431d-b5f9-6f1512de2331', 'Mikrobiologie', 'Welcher Erreger verursacht typischerweise Pfeiffersches Druesenfieber?', '["Epstein-Barr-Virus", "Cytomegalievirus", "Influenza-A", "Adenovirus"]', 'Epstein-Barr-Virus', '2025-12-19 13:44:51.555638+00', 'mikrobiologie-epstein-barr', '2026-02-03 19:51:09.907698+00', 'Das Epstein-Barr-Virus infiziert B-Zellen und verursacht infektioese Mononukleose. Typisch sind Halsschmerzen, Lymphknotenschwellung und Splenomegalie.'),
	('776cc74b-8b03-4913-a393-f322e0cb56b1', 'Pathologie', 'Welche Zelle ist charakteristisch fuer das Hodgkin-Lymphom?', '["Reed-Sternberg-Zelle", "Touton-Riesenzelle", "Langhans-Riesenzelle", "Aschoff-Knoetchen"]', 'Reed-Sternberg-Zelle', '2025-12-19 13:44:51.555638+00', 'pathologie-reed-sternberg', '2026-02-03 19:51:09.907698+00', 'Reed-Sternberg-Zellen sind grosse, binukleare B-Zellen und das diagnostische Merkmal des Hodgkin-Lymphoms. Sie exprimieren typischerweise CD15 und CD30.'),
	('0fef04f2-2f1e-4038-8a19-659faa2227df', 'Anatomie', 'Wie heisst der Knochen des Oberarms?', '["Humerus", "Radius", "Ulna", "Femur"]', 'Humerus', '2025-12-19 15:21:08.121842+00', 'anatomie-leicht-01', '2026-02-03 19:51:09.907698+00', 'Der Humerus bildet den Oberarm und verbindet Schulter mit dem Ellenbogen. Proximal artikuliert er mit der Scapula, distal mit Radius und Ulna.'),
	('e53f09cd-6a3a-48c7-99ea-61bde91d10e4', 'Anatomie', 'Welcher Muskel ist der groesste im menschlichen Koerper?', '["M. gluteus maximus", "M. biceps brachii", "M. deltoideus", "M. rectus abdominis"]', 'M. gluteus maximus', '2025-12-19 15:21:08.121842+00', 'anatomie-leicht-03', '2026-02-03 19:51:09.907698+00', 'Der M. gluteus maximus ist der groesste Muskel des Koerpers. Er streckt die Huefte und ist wichtig beim Aufstehen und Treppensteigen.'),
	('62a4942b-572a-4bdf-857f-a80472d2e075', 'Anatomie', 'Welches Organ liegt im linken Oberbauch?', '["Milz", "Leber", "Appendix", "Gallenblase"]', 'Milz', '2025-12-19 15:21:08.121842+00', 'anatomie-leicht-04', '2026-02-03 19:51:09.907698+00', 'Die Milz liegt im linken Oberbauch unter dem Rippenbogen. Sie filtert Blut, baut alte Erythrozyten ab und unterstuetzt die Immunabwehr.'),
	('1da65072-c375-4c64-8441-d0ff9fe44138', 'Anatomie', 'Wie heisst der Knochen der Kniescheibe?', '["Patella", "Tibia", "Fibula", "Talus"]', 'Patella', '2025-12-19 15:21:08.121842+00', 'anatomie-leicht-05', '2026-02-03 19:51:09.907698+00', 'Die Patella ist ein Sesambein in der Quadrizepssehne. Sie vergroessert den Hebelarm des Kniestreckers und schuetzt das Gelenk.'),
	('e49d0321-bcf4-4f86-8657-a9be5bfe346b', 'Anatomie', 'Welcher Nerv innerviert den Musculus biceps brachii motorisch?', '["N. musculocutaneus", "N. radialis", "N. medianus", "N. ulnaris"]', 'N. musculocutaneus', '2025-12-19 15:21:08.121842+00', 'anatomie-mittel-01', '2026-02-03 19:51:09.907698+00', 'Der N. musculocutaneus stammt aus dem Plexus brachialis (C5-C7) und innerviert Bizeps und Brachialis. Sensibel versorgt er die laterale Unterarmhaut.'),
	('fdfa6af3-13a5-45dc-a782-4e6681a0060d', 'Anatomie', 'Welche Struktur trennt rechten und linken Vorhof?', '["Vorhofseptum", "Ventrikelseptum", "Aortenklappe", "Trikuspidalklappe"]', 'Vorhofseptum', '2025-12-19 15:21:08.121842+00', 'anatomie-mittel-02', '2026-02-03 19:51:09.907698+00', 'Das Vorhofseptum trennt rechten und linken Vorhof. Ein persistierendes Foramen ovale kann einen Rechts-Links-Shunt ermoeglichen.'),
	('de9b669c-e8ca-45d7-a6a7-c55bda824d92', 'Anatomie', 'Welche Arterie versorgt den vorderen Hirnkreislauf hauptsaechlich?', '["A. carotis interna", "A. vertebralis", "A. basilaris", "A. subclavia"]', 'A. carotis interna', '2025-12-19 15:21:08.121842+00', 'anatomie-mittel-03', '2026-02-03 19:51:09.907698+00', 'Die A. carotis interna versorgt den vorderen Hirnkreislauf und teilt sich in A. cerebri anterior und media. Sie speist grosse Teile der Grosshirnhemisphaeren.'),
	('ed1a07ac-1ce8-4ea2-a1fe-4b2651d01dbb', 'Anatomie', 'Wo liegt das Foramen magnum?', '["Os occipitale", "Os frontale", "Os temporale", "Os sphenoidale"]', 'Os occipitale', '2025-12-19 15:21:08.121842+00', 'anatomie-mittel-05', '2026-02-03 19:51:09.907698+00', 'Das Foramen magnum liegt im Os occipitale. Durch die Oeffnung ziehen Medulla oblongata, Meningen und die Aa. vertebrales.'),
	('1112fc78-38b3-4990-a5ed-ca001ebaac29', 'Anatomie', 'Welche Struktur verlaesst die Fossa cranii media durch das Foramen ovale?', '["N. mandibularis (V3)", "N. oculomotorius (III)", "N. facialis (VII)", "N. abducens (VI)"]', 'N. mandibularis (V3)', '2025-12-19 15:21:08.121842+00', 'anatomie-schwer-01', '2026-02-03 19:51:09.907698+00', 'Durch das Foramen ovale zieht der N. mandibularis (V3) aus der mittleren Schaedelgrube. Er fuehrt motorische Fasern fuer die Kaumuskulatur und sensible Fasern fuer den Unterkiefer.'),
	('8fad91c1-d7f6-4c5e-a33b-671d79ecc92c', 'Chirurgie', 'Welche Narkoseform wird für grosse Bauchoperationen typischerweise genutzt?', '["Allgemeinanästhesie", "Lokalanästhesie", "Regionalanästhesie", "Sedierung ohne Analgesie"]', 'Allgemeinanästhesie', '2026-01-30 21:45:58.910706+00', 'chirurgie-extra-2026-02', '2026-03-14 13:27:24.246299+00', 'Groessere Bauchoperationen erfolgen meist in Allgemeinanaesthesie, weil sie sichere Atemwegskontrolle, ausreichende Analgesie und Muskelrelaxation erlaubt.'),
	('ab0d49cf-7f9a-43e6-b32f-192c66ee4c08', 'Anatomie', 'Welcher Muskel gehoert zur Rotatorenmanschette?', '["M. supraspinatus", "M. pectoralis major", "M. latissimus dorsi", "M. serratus anterior"]', 'M. supraspinatus', '2025-12-19 15:21:08.121842+00', 'anatomie-schwer-02', '2026-02-03 19:51:09.907698+00', 'Zur Rotatorenmanschette gehoeren Supraspinatus, Infraspinatus, Teres minor und Subscapularis. Sie stabilisieren das Schultergelenk und ermoeglichen Rotation.'),
	('1009aa82-9a22-42f4-88e6-ac6a774ee72d', 'Anatomie', 'Welcher Ast der A. iliaca interna versorgt die Harnblase?', '["A. vesicalis superior", "A. obturatoria", "A. glutea superior", "A. pudenda interna"]', 'A. vesicalis superior', '2025-12-19 15:21:08.121842+00', 'anatomie-schwer-03', '2026-02-03 19:51:09.907698+00', 'Die A. vesicalis superior entspringt aus der A. iliaca interna, meist als Ast der A. umbilicalis. Sie versorgt den oberen Teil der Harnblase.'),
	('966e868d-5750-4a00-bac8-27db7db1e82c', 'Anatomie', 'Welcher Wirbel besitzt einen Dens?', '["Axis (C2)", "Atlas (C1)", "C3", "C7"]', 'Axis (C2)', '2025-12-19 15:21:08.121842+00', 'anatomie-schwer-04', '2026-02-03 19:51:09.907698+00', 'Der Axis (C2) besitzt den Dens axis. Er bildet das Drehgelenk mit dem Atlas und ermoeglicht die Kopfdrehung.'),
	('c3e499ce-81f7-443f-b74e-0a8f5c026b32', 'Anatomie', 'Welche Schicht der Darmwand liegt direkt unter der Mukosa?', '["Submukosa", "Muskularis propria", "Serosa", "Adventitia"]', 'Submukosa', '2025-12-19 15:21:08.121842+00', 'anatomie-schwer-05', '2026-02-03 19:51:09.907698+00', 'Die Submukosa liegt direkt unter der Mukosa und enthaelt Gefaesse, Lymphbahnen und den Plexus submucosus. Sie ist wichtig fuer Sekretion und Durchblutung.'),
	('c33d5c8b-7837-4473-9e24-9bae1b06bb55', 'Physiologie', 'Welches Hormon steigert den Blutzuckerspiegel?', '["Glukagon", "Insulin", "Aldosteron", "Oxytocin"]', 'Glukagon', '2025-12-19 15:21:08.121842+00', 'physiologie-leicht-01', '2026-02-03 19:51:09.907698+00', 'Glukagon wird in den Alpha-Zellen des Pankreas gebildet. Es steigert den Blutzucker durch Glykogenolyse und Glukoneogenese und wirkt Insulin entgegen.'),
	('b1641c81-fd1e-4e52-ad8c-6130a2e75bf0', 'Physiologie', 'Wie viel Prozent Sauerstoff enthaelt die Einatemluft ungefaehr?', '["21 %", "16 %", "10 %", "40 %"]', '21 %', '2025-12-19 15:21:08.121842+00', 'physiologie-leicht-02', '2026-02-03 19:51:09.907698+00', 'Die Einatemluft enthaelt etwa 21 % O2. In den Alveolen ist der O2-Anteil geringer, weil Wasserdampf und CO2 den Partialdruck senken.'),
	('96097493-dfbe-4892-b228-76e362adfc97', 'Physiologie', 'Welche Ionen sind hauptsaechlich fuer das Ruhemembranpotential verantwortlich?', '["Kalium", "Natrium", "Calcium", "Chlorid"]', 'Kalium', '2025-12-19 15:21:08.121842+00', 'physiologie-leicht-03', '2026-02-03 19:51:09.907698+00', 'Kalium bestimmt das Ruhemembranpotential, da die Membran in Ruhe vor allem fuer K+ permeabel ist. Die Na/K-ATPase haelt den Konzentrationsgradienten aufrecht.'),
	('d44229ba-183f-4251-8523-ad5fa0e7dc92', 'Physiologie', 'Wie heisst der Herzschrittmacher im rechten Vorhof?', '["Sinusknoten", "AV-Knoten", "Purkinje-Fasern", "His-Buendel"]', 'Sinusknoten', '2025-12-19 15:21:08.121842+00', 'physiologie-leicht-04', '2026-02-03 19:51:09.907698+00', 'Der Sinusknoten im rechten Vorhof erzeugt den Grundrhythmus des Herzens. Er feuert spontan und gibt typischerweise 60 bis 100 Impulse pro Minute vor.'),
	('d2085e6f-11ce-4ee6-bae6-09c2ebec1e16', 'Physiologie', 'Welches System reguliert den Kurzzeit-Blutdruck?', '["Barorezeptoren", "Chemorezeptoren", "Hypothalamus", "Nebennierenrinde"]', 'Barorezeptoren', '2025-12-19 15:21:08.121842+00', 'physiologie-leicht-05', '2026-02-03 19:51:09.907698+00', 'Barorezeptoren im Karotissinus und Aortenbogen messen Druckaenderungen. Ueber vegetative Reflexe regulieren sie kurzfristig Herzfrequenz und Gefaesstonus.'),
	('b50c2792-a1c1-4dca-b54b-c8174f8b54c3', 'Physiologie', 'Welcher Transportmechanismus nutzt ATP direkt?', '["Primaer aktiver Transport", "Erleichterte Diffusion", "Osmose", "Filtration"]', 'Primaer aktiver Transport', '2025-12-19 15:21:08.121842+00', 'physiologie-mittel-01', '2026-02-03 19:51:09.907698+00', 'Primaer aktiver Transport nutzt ATP direkt, z. B. die Na/K-ATPase. Sekundaer aktiver Transport verwendet den aufgebauten Ionengradienten.'),
	('d540f41c-32cb-48b7-81f7-082269a1a830', 'Physiologie', 'Welche Saeure wird von Belegzellen im Magen gebildet?', '["Salzsaeure", "Milchsaeure", "Kohlensaeure", "Essigsaeure"]', 'Salzsaeure', '2025-12-19 15:21:08.121842+00', 'physiologie-mittel-02', '2026-02-03 19:51:09.907698+00', 'Belegzellen produzieren Salzsaeure mit sehr niedrigem pH. Sie aktiviert Pepsinogen und dient der Keimabwehr; ausserdem bilden Belegzellen den Intrinsic Factor.'),
	('3bf83df5-2ec6-48fc-9d53-929b725818fc', 'Physiologie', 'Wie lange leben Erythrozyten ungefaehr?', '["30 Tage", "60 Tage", "120 Tage", "300 Tage"]', '120 Tage', '2025-12-19 15:21:08.121842+00', 'physiologie-mittel-03', '2026-02-03 19:51:09.907698+00', 'Erythrozyten leben etwa 120 Tage und werden vor allem in der Milz abgebaut. Da sie keinen Zellkern besitzen, koennen sie keine Proteine nachbilden.'),
	('62979bec-4777-4663-a02f-54ba2c510fe4', 'Physiologie', 'Welche Struktur ist der Ort des Gasaustauschs in der Lunge?', '["Alveolen", "Bronchien", "Pleura", "Trachea"]', 'Alveolen', '2025-12-19 15:21:08.121842+00', 'physiologie-mittel-04', '2026-02-03 19:51:09.907698+00', 'Die Alveolen sind der Ort des Gasaustauschs mit extrem duennen Waenden und grosser Oberflaeche. O2 diffundiert ins Blut, CO2 in die Ausatemluft.'),
	('38b86eb0-1b0f-4755-bb43-83dd916e4963', 'Physiologie', 'Welches Hormon foerdert die Wasserresorption in der Niere?', '["ADH (Vasopressin)", "Aldosteron", "ANP", "Cortisol"]', 'ADH (Vasopressin)', '2025-12-19 15:21:08.121842+00', 'physiologie-mittel-05', '2026-02-03 19:51:09.907698+00', 'ADH wird im Hypothalamus gebildet und aus dem Hypophysenhinterlappen freigesetzt. Es foerdert Aquaporine im Sammelrohr und steigert die Wasserresorption.'),
	('7e8af7b5-e199-4689-8945-1d2d5b9c3975', 'Physiologie', 'Welche Stromart verursacht die Phase-0-Depolarisation im Sinusknoten?', '["Calcium-Einstrom (L-Typ)", "Natrium-Einstrom (schnell)", "Kalium-Ausstrom", "Chlorid-Einstrom"]', 'Calcium-Einstrom (L-Typ)', '2025-12-19 15:21:08.121842+00', 'physiologie-schwer-01', '2026-02-03 19:51:09.907698+00', 'Im Sinusknoten entsteht Phase 0 durch L-Typ-Calciumkanaele, nicht durch schnelle Natriumkanaele. Das erklaert den langsameren Aufstrich der Aktionspotentiale.'),
	('c0753bf0-f020-4249-87be-775a57dc35cd', 'Physiologie', 'Welcher Teil des Nephrons ist fuer die Gegenstrommultiplikation entscheidend?', '["Henle-Schleife", "Bowman-Kapsel", "Proximaler Tubulus", "Sammelrohr"]', 'Henle-Schleife', '2025-12-19 15:21:08.121842+00', 'physiologie-schwer-02', '2026-02-03 19:51:09.907698+00', 'Die Henle-Schleife erzeugt den Gegenstromgradienten in der Nierenmarksubstanz. Der dicke aufsteigende Ast transportiert NaCl ohne Wasser und macht das Interstitium hyperosmolar.'),
	('056bba62-bbfd-4419-b6f1-d4614158de3a', 'Physiologie', 'Welcher Faktor verschiebt die O2-Bindungskurve nach rechts?', '["pH-Abfall (Bohr-Effekt)", "pH-Anstieg", "Temperaturabfall", "CO2-Abfall"]', 'pH-Abfall (Bohr-Effekt)', '2025-12-19 15:21:08.121842+00', 'physiologie-schwer-03', '2026-02-03 19:51:09.907698+00', 'Ein pH-Abfall verschiebt die O2-Bindungskurve nach rechts und erleichtert die O2-Abgabe im Gewebe. Aehnlich wirken Temperaturanstieg, CO2-Anstieg und mehr 2,3-BPG.'),
	('65427de1-2938-4516-8750-c57bb78fcbfd', 'Physiologie', 'Wann findet die isovolumetrische Kontraktion statt?', '["Direkt nach AV-Klappenschluss", "Waerend der Auswurfphase", "Waerend der Ventrikelfuellung", "Nach Oeffnung der AV-Klappen"]', 'Direkt nach AV-Klappenschluss', '2025-12-19 15:21:08.121842+00', 'physiologie-schwer-04', '2026-02-03 19:51:09.907698+00', 'Die isovolumetrische Kontraktion beginnt direkt nach Schluss der AV-Klappen. Der Ventrikeldruck steigt bei konstantem Volumen, bis die Taschenklappen oeffnen.'),
	('56f99921-0a80-4453-bdae-80c5261d2dc1', 'Physiologie', 'Welche Zellen produzieren Surfactant in der Lunge?', '["Pneumozyten Typ II", "Pneumozyten Typ I", "Alveolarmakrophagen", "Endothelzellen"]', 'Pneumozyten Typ II', '2025-12-19 15:21:08.121842+00', 'physiologie-schwer-05', '2026-02-03 19:51:09.907698+00', 'Pneumozyten Typ II produzieren Surfactant und senken die Oberflaechenspannung der Alveolen. Sie koennen sich teilen und Typ-I-Zellen ersetzen.'),
	('a0099877-5ac5-4820-89fb-9ea0780f16cf', 'Pathologie', 'Wie nennt man eine gutartige Geschwulst des Fettgewebes?', '["Lipom", "Sarkom", "Melanom", "Lymphom"]', 'Lipom', '2025-12-19 15:21:08.121842+00', 'pathologie-leicht-01', '2026-02-03 19:51:09.907698+00', 'Ein Lipom ist ein gutartiger Tumor des Fettgewebes. Es ist meist weich, verschieblich und langsam wachsend.'),
	('91ef07db-75eb-49b1-9799-58b25528d1cd', 'Pathologie', 'Was bezeichnet man als Fieber?', '["Koerpertemperatur ueber 38 C", "Koerpertemperatur unter 36 C", "Koerpertemperatur 37 C", "Koerpertemperatur unter 35 C"]', 'Koerpertemperatur ueber 38 C', '2025-12-19 15:21:08.121842+00', 'pathologie-leicht-03', '2026-02-03 19:51:09.907698+00', 'Fieber ist eine Erhoehung der Koerperkerntemperatur ueber 38 C durch einen hoeheren Sollwert im Hypothalamus. Pyrogene Zytokine sind eine haeufige Ursache.'),
	('9d5321a6-932b-4a3c-a836-e725486616b8', 'Pathologie', 'Wie nennt man Gewebsuntergang durch Durchblutungsstoerung?', '["Infarkt", "Hyperplasie", "Dysplasie", "Metaplasie"]', 'Infarkt', '2025-12-19 15:21:08.121842+00', 'pathologie-leicht-04', '2026-02-03 19:51:09.907698+00', 'Ein Infarkt ist Gewebsuntergang durch akute Ischaemie. Typische Beispiele sind Myokard- oder Hirninfarkt.'),
	('ad68888b-3122-446a-bdb8-49e10e16f840', 'Pathologie', 'Welche Blutungsform zeigt punktfoermige Hauteinblutungen?', '["Petechien", "Haematome", "Ulcera", "Varizen"]', 'Petechien', '2025-12-19 15:21:08.121842+00', 'pathologie-leicht-05', '2026-02-03 19:51:09.907698+00', 'Petechien sind punktfoermige Hauteinblutungen durch Kapillarschaedigung oder Thrombozytopenie. Sie sind nicht wegdrueckbar.'),
	('554e117d-389b-40ef-9148-9aca6106a613', 'Pathologie', 'Welcher Tumormarker ist typisch erhoeht beim Prostatakarzinom?', '["PSA", "AFP", "CEA", "CA-125"]', 'PSA', '2025-12-19 15:21:08.121842+00', 'pathologie-mittel-01', '2026-02-03 19:51:09.907698+00', 'PSA ist ein Marker fuer Prostatagewebe und wird bei Karzinom erhoeht gefunden. Er kann aber auch bei benigner Prostatahyperplasie ansteigen, daher dient er vor allem der Verlaufskontrolle.'),
	('ec6c8564-a45a-44d5-b20f-c4b2fae0b6c6', 'Pathologie', 'Welche Nekroseform ist typisch beim Myokardinfarkt?', '["Koagulationsnekrose", "Kolliquationsnekrose", "Fettgewebsnekrose", "Fibrinoidnekrose"]', 'Koagulationsnekrose', '2025-12-19 15:21:08.121842+00', 'pathologie-mittel-02', '2026-02-03 19:51:09.907698+00', 'Koagulationsnekrose ist typisch bei ischaemischen Infarkten des Herzens. Die Gewebsarchitektur bleibt zunaechst erhalten, obwohl Zellen abgestorben sind.'),
	('38684ecc-9685-4d1a-9b66-16db717c2e77', 'Pathologie', 'Was beschreibt eine Metaplasie?', '["Reversible Umwandlung eines Zelltyps in einen anderen", "Vermehrung der Zellzahl", "Zellgroessenzunahme", "Ungeordnete Zellproliferation"]', 'Reversible Umwandlung eines Zelltyps in einen anderen', '2025-12-19 15:21:08.121842+00', 'pathologie-mittel-03', '2026-02-03 19:51:09.907698+00', 'Metaplasie ist eine reversible Anpassung an chronische Reize. Beispiel ist Plattenepithelmetaplasie in den Bronchien von Rauchern.'),
	('b9ee9395-4126-4148-a2b8-907363655f23', 'Pathologie', 'Welche Autoimmunthyreoiditis ist haeufig?', '["Hashimoto-Thyreoiditis", "Basedow", "Riedel-Struma", "Kretinismus"]', 'Hashimoto-Thyreoiditis', '2025-12-19 15:21:08.121842+00', 'pathologie-mittel-04', '2026-02-03 19:51:09.907698+00', 'Hashimoto-Thyreoiditis ist eine autoimmune Schilddruesenentzuendung mit Anti-TPO-Antikoerpern. Sie fuehrt haeufig zu Hypothyreose.'),
	('b71ae44d-18b6-43af-9f5a-df0200e2d367', 'Pathologie', 'Welche Zellen spielen bei der Typ-I-Allergie die Hauptrolle?', '["Mastzellen", "Neutrophile", "Erythrozyten", "Thrombozyten"]', 'Mastzellen', '2025-12-19 15:21:08.121842+00', 'pathologie-mittel-05', '2026-02-03 19:51:09.907698+00', 'Mastzellen tragen IgE auf der Oberflaeche und degranulieren nach Allergenkontakt. Histamin verursacht Juckreiz, Quaddeln und Bronchospasmus.'),
	('4e9a0a79-04da-4a5a-9558-8ec80b3789f6', 'Pathologie', 'Welche Translokation ist typisch fuer die CML?', '["t(9;22) BCR-ABL", "t(8;14)", "t(15;17)", "t(14;18)"]', 't(9;22) BCR-ABL', '2025-12-19 15:21:08.121842+00', 'pathologie-schwer-01', '2026-02-03 19:51:09.907698+00', 't(9;22) erzeugt das BCR-ABL-Fusionsprotein, das als Tyrosinkinase dauerhaft aktiv ist. Dieses Philadelphia-Chromosom ist typisch fuer CML und Ziel von Imatinib.'),
	('de528926-fac5-44ef-a7d5-2b8aa95dfc8a', 'Pathologie', 'Welche Amyloidose ist typisch beim multiplen Myelom?', '["AL-Amyloid", "AA-Amyloid", "ATTR", "Abeta"]', 'AL-Amyloid', '2025-12-19 15:21:08.121842+00', 'pathologie-schwer-02', '2026-02-03 19:51:09.907698+00', 'AL-Amyloid besteht aus Immunglobulin-Leichtketten. Es tritt bei Plasmazellerkrankungen wie multiplem Myelom auf und kann Organe infiltrieren.'),
	('315f3e48-e249-4eed-9e7b-7ea48ef52c25', 'Pathologie', 'Welche Virusinfektion ist mit Zervixkarzinom assoziiert?', '["HPV 16/18", "EBV", "CMV", "HSV-1"]', 'HPV 16/18', '2025-12-19 15:21:08.121842+00', 'pathologie-schwer-03', '2026-02-03 19:51:09.907698+00', 'HPV 16 und 18 sind Hochrisiko-Typen fuer Zervixkarzinom. Die Onkoproteine E6 und E7 inaktivieren p53 und Rb.'),
	('c6eabeb3-028f-4515-bae4-cce2a620f7e1', 'Pathologie', 'Welcher Autoantikoerper ist typisch beim Goodpasture-Syndrom?', '["Anti-GBM", "ANA", "c-ANCA", "Rheumafaktor"]', 'Anti-GBM', '2025-12-19 15:21:08.121842+00', 'pathologie-schwer-04', '2026-02-03 19:51:09.907698+00', 'Anti-GBM-Antikoerper richten sich gegen die Basalmembran von Lunge und Niere. Klinisch zeigen sich Haemoptysen und rasch progrediente Glomerulonephritis.'),
	('1ef4a2a4-7ea6-47e9-b7a5-dcec723622f2', 'Pathologie', 'Welche Tumorsuppressor-Genmutation ist typisch beim Retinoblastom?', '["RB1", "p53", "APC", "BRCA1"]', 'RB1', '2025-12-19 15:21:08.121842+00', 'pathologie-schwer-05', '2026-02-03 19:51:09.907698+00', 'RB1 ist ein Tumorsuppressor, der nach dem Zwei-Treffer-Modell inaktiviert wird. Das fuehrt zu Retinoblastom, oft bilateral bei erblichen Faellen.'),
	('0ad67819-d288-49cd-b06b-eff433920bb1', 'Pharmakologie', 'Welches Analgetikum ist ein NSAID?', '["Ibuprofen", "Paracetamol", "Morphin", "Amitriptylin"]', 'Ibuprofen', '2025-12-19 15:21:08.121842+00', 'pharmakologie-leicht-01', '2026-02-03 19:51:09.907698+00', 'Ibuprofen hemmt COX-1 und COX-2 und reduziert Prostaglandine. Dadurch wirkt es analgetisch, antipyretisch und antiinflammatorisch.'),
	('966f60e7-2250-458e-8017-cd530efa6829', 'Pharmakologie', 'Welcher Wirkstoff ist ein Beta-Blocker?', '["Metoprolol", "Amlodipin", "Losartan", "Furosemid"]', 'Metoprolol', '2025-12-19 15:21:08.121842+00', 'pharmakologie-leicht-02', '2026-02-03 19:51:09.907698+00', 'Metoprolol ist ein selektiver Beta1-Blocker. Er senkt Herzfrequenz und Blutdruck und reduziert den Sauerstoffbedarf des Herzens.'),
	('5bc0d7b7-974b-4576-88a8-8a4157c76794', 'Pharmakologie', 'Welche Substanz ist ein Penicillin-Antibiotikum?', '["Amoxicillin", "Azithromycin", "Doxycyclin", "Ciprofloxacin"]', 'Amoxicillin', '2025-12-19 15:21:08.121842+00', 'pharmakologie-leicht-03', '2026-02-03 19:51:09.907698+00', 'Amoxicillin ist ein Beta-Laktam-Antibiotikum, das die Zellwandsynthese hemmt. Es wirkt bakterizid und hat ein breites Spektrum.'),
	('936b16ef-e127-49b2-81c5-fa3893d34a2a', 'Pharmakologie', 'Welches Medikament ist ein Protonenpumpenhemmer?', '["Omeprazol", "Ranitidin", "Metoclopramid", "Sucralfat"]', 'Omeprazol', '2025-12-19 15:21:08.121842+00', 'pharmakologie-leicht-04', '2026-02-03 19:51:09.907698+00', 'Omeprazol ist ein Protonenpumpenhemmer und blockiert die H+/K+-ATPase irreversibel. Dadurch sinkt die Saeureproduktion im Magen.'),
	('6bc365c5-4414-416b-ba4c-225ff5d5de76', 'Pharmakologie', 'Welche Substanz ist ein Opioid?', '["Morphin", "Diclofenac", "Ibuprofen", "Paracetamol"]', 'Morphin', '2025-12-19 15:21:08.121842+00', 'pharmakologie-leicht-05', '2026-02-03 19:51:09.907698+00', 'Morphin ist ein starker Opioid-Agonist am mu-Rezeptor. Neben Analgesie koennen Atemdepression und Abhaengigkeit auftreten.'),
	('8e70d315-c871-4f04-9b83-605be88b3f5f', 'Pharmakologie', 'Welcher Wirkstoff hemmt die HMG-CoA-Reduktase?', '["Atorvastatin", "Ezetimib", "Fenofibrat", "Niacin"]', 'Atorvastatin', '2025-12-19 15:21:08.121842+00', 'pharmakologie-mittel-01', '2026-02-03 19:51:09.907698+00', 'Atorvastatin hemmt die HMG-CoA-Reduktase und senkt die Cholesterinsynthese. Das reduziert LDL und das Risiko atherosklerotischer Ereignisse.'),
	('c45408e3-34a5-453a-8535-9c1c37faaa80', 'Pharmakologie', 'Welches Diuretikum wirkt am aufsteigenden Ast der Henle-Schleife?', '["Furosemid", "Hydrochlorothiazid", "Spironolacton", "Acetazolamid"]', 'Furosemid', '2025-12-19 15:21:08.121842+00', 'pharmakologie-mittel-02', '2026-02-03 19:51:09.907698+00', 'Furosemid hemmt den Na-K-2Cl-Cotransporter im dicken aufsteigenden Ast der Henle-Schleife. Es verursacht starke Diurese und kann Hypokaliaemie ausloesen.'),
	('eef51cf2-a4e1-4da6-8d65-fc04bb6c4673', 'Pharmakologie', 'Welche typische Nebenwirkung von ACE-Hemmern ist korrekt?', '["Trockener Husten", "Hypoglykaemie", "Bradykardie", "Hyperthyreose"]', 'Trockener Husten', '2025-12-19 15:21:08.121842+00', 'pharmakologie-mittel-03', '2026-02-03 19:51:09.907698+00', 'ACE-Hemmer erhoehen Bradykinin, was trockenen Reizhusten ausloesen kann. Deshalb wird bei Husten oft auf AT1-Blocker gewechselt.'),
	('f01973ba-8e74-416e-b585-f6d15834b4fe', 'Pharmakologie', 'Welcher Wirkstoff ist ein nicht-depolarisierendes Muskelrelaxans?', '["Rocuronium", "Succinylcholin", "Neostigmin", "Midazolam"]', 'Rocuronium', '2025-12-19 15:21:08.121842+00', 'pharmakologie-schwer-02', '2026-02-03 19:51:09.907698+00', 'Rocuronium blockiert nikotinische ACh-Rezeptoren an der motorischen Endplatte kompetitiv. Die Laehmung kann mit Sugammadex aufgehoben werden.'),
	('0b8f1131-f810-4485-8c32-337cc398b369', 'Pharmakologie', 'Welches Antiarrhythmikum gehoert zu Klasse III?', '["Amiodaron", "Lidocain", "Verapamil", "Propranolol"]', 'Amiodaron', '2025-12-19 15:21:08.121842+00', 'pharmakologie-schwer-03', '2026-02-03 19:51:09.907698+00', 'Amiodaron blockiert vor allem K-Kanaele und verlaengert die Repolarisation (Klasse III). Es kann aber Schilddruese, Lunge und Leber schaedigen.'),
	('4063c3a0-c4cd-40ac-931c-6022a1cb736d', 'Pharmakologie', 'Welche Substanz ist ein monoklonaler Anti-TNF-Antikoerper?', '["Infliximab", "Rituximab", "Trastuzumab", "Bevacizumab"]', 'Infliximab', '2025-12-19 15:21:08.121842+00', 'pharmakologie-schwer-04', '2026-02-03 19:51:09.907698+00', 'Infliximab ist ein monoklonaler Antikoerper gegen TNF-alpha. Es wird bei Autoimmunerkrankungen eingesetzt und erhoeht das Risiko fuer Infektionen wie Tuberkulose.'),
	('bfa1fc81-91d5-4882-990c-91dc08445b8f', 'Pharmakologie', 'Welcher Wirkmechanismus trifft auf Heparin zu?', '["Aktivierung von Antithrombin III", "Vitamin-K-Antagonismus", "Direkte Thrombinhemmung", "Hemmung der Thrombozytenaggregation"]', 'Aktivierung von Antithrombin III', '2025-12-19 15:21:08.121842+00', 'pharmakologie-schwer-05', '2026-02-03 19:51:09.907698+00', 'Heparin aktiviert Antithrombin III und hemmt dadurch Thrombin und Faktor Xa. Die Wirkung tritt sofort ein und wird ueber die aPTT gesteuert.'),
	('e985b45c-39f0-4de8-b376-dc690f52ce68', 'Mikrobiologie', 'Welches Bakterium ist grampositiv?', '["Staphylococcus aureus", "Escherichia coli", "Pseudomonas aeruginosa", "Neisseria meningitidis"]', 'Staphylococcus aureus', '2025-12-19 15:21:08.121842+00', 'mikrobiologie-leicht-01', '2026-02-03 19:51:09.907698+00', 'Staphylococcus aureus ist ein grampositiver Kokkus in Traubenlagerung. Er ist koagulasepositiv und haeufige Ursache von Haut- und Weichteilinfektionen.'),
	('5a08e946-efb6-4366-b363-e89c6696d23a', 'Mikrobiologie', 'Welche Struktur nutzen Bakterien zur Bewegung?', '["Flagellen", "Pili", "Kapsel", "Ribosomen"]', 'Flagellen', '2025-12-19 15:21:08.121842+00', 'mikrobiologie-leicht-02', '2026-02-03 19:51:09.907698+00', 'Flagellen sind fadenfoermige Strukturen aus Flagellin. Sie ermoeglichen Bewegung und Chemotaxis in Fluessigkeiten.'),
	('56024eed-9eca-46c7-83e1-1ed0df1435a2', 'Mikrobiologie', 'Wie nennt man Viren mit RNA als Erbmaterial?', '["RNA-Viren", "DNA-Viren", "Prionen", "Pilze"]', 'RNA-Viren', '2025-12-19 15:21:08.121842+00', 'mikrobiologie-leicht-03', '2026-02-03 19:51:09.907698+00', 'RNA-Viren besitzen RNA als Genom und benoetigen eine RNA-abhaengige RNA-Polymerase. Sie mutieren meist schneller als DNA-Viren.'),
	('6ca8a644-f5c2-4ab7-8932-13d39801cf75', 'Mikrobiologie', 'Welche Pilzinfektion betrifft haeufig die Haut?', '["Tinea", "Malaria", "Lepra", "Zoster"]', 'Tinea', '2025-12-19 15:21:08.121842+00', 'mikrobiologie-leicht-04', '2026-02-03 19:51:09.907698+00', 'Tinea ist eine Dermatophyteninfektion der Haut. Erreger wie Trichophyton nutzen Keratin in Haut, Haaren oder Naegeln.'),
	('734fe0bf-9964-4634-89fd-32675409a8bb', 'Mikrobiologie', 'Welcher Erreger verursacht Masern?', '["Masernvirus", "Varizella-Zoster-Virus", "Influenzavirus", "Adenovirus"]', 'Masernvirus', '2025-12-19 15:21:08.121842+00', 'mikrobiologie-leicht-05', '2026-02-03 19:51:09.907698+00', 'Masern werden durch das Masernvirus verursacht. Typisch sind Fieber, Exanthem und eine voruebergehende Immunsuppression.'),
	('465f3868-0af1-48c5-ad9d-94102ce039d2', 'Mikrobiologie', 'Welcher Erreger verursacht typischerweise Harnwegsinfekte?', '["Escherichia coli", "Streptococcus pyogenes", "Mycoplasma pneumoniae", "Treponema pallidum"]', 'Escherichia coli', '2025-12-19 15:21:08.121842+00', 'mikrobiologie-mittel-01', '2026-02-03 19:51:09.907698+00', 'Escherichia coli stammt haeufig aus der Darmflora und besitzt Adhaesionsfaktoren fuer Uroepithel. Deshalb verursacht es die meisten unkomplizierten Harnwegsinfekte.'),
	('1a453c71-d6ed-4d40-a36a-a2287258a59a', 'Mikrobiologie', 'Welches Bakterium verursacht Tetanus?', '["Clostridium tetani", "Corynebacterium diphtheriae", "Borrelia burgdorferi", "Campylobacter jejuni"]', 'Clostridium tetani', '2025-12-19 15:21:08.121842+00', 'mikrobiologie-mittel-02', '2026-02-03 19:51:09.907698+00', 'Clostridium tetani ist anaerob und bildet Sporen. Sein Tetanospasmin blockiert inhibitorische Neurone und fuehrt zu spastischen Kraempfen.'),
	('4eeaea21-8311-456b-b8dc-2f93c3220d43', 'Mikrobiologie', 'Welche Viren sind typisch fuer Gastroenteritis bei Kindern?', '["Rotavirus", "EBV", "HSV-1", "Parvovirus B19"]', 'Rotavirus', '2025-12-19 15:21:08.121842+00', 'mikrobiologie-mittel-03', '2026-02-03 19:51:09.907698+00', 'Rotaviren sind eine der haeufigsten Ursachen kindlicher Gastroenteritis. Sie verursachen waessrige Diarrhoe und koennen zu schneller Dehydratation fuehren.'),
	('eaee7919-db71-4fbf-ba33-8b5747d24b84', 'Mikrobiologie', 'Welche Eigenschaft hat Mycobacterium tuberculosis?', '["Saeurefest", "Sporenbildend", "Gramnegativ", "Kapselbildend"]', 'Saeurefest', '2025-12-19 15:21:08.121842+00', 'mikrobiologie-mittel-04', '2026-02-03 19:51:09.907698+00', 'Mycobacterium tuberculosis ist saeurefest wegen Mykolsauren in der Zellwand. Dadurch benoetigt es spezielle Faerbungen wie Ziehl-Neelsen.'),
	('40d6e149-4421-4c7e-90ec-817b3d36eb64', 'Mikrobiologie', 'Welcher Erreger verursacht eine atypische Pneumonie?', '["Mycoplasma pneumoniae", "Streptococcus pneumoniae", "Haemophilus influenzae", "Moraxella catarrhalis"]', 'Mycoplasma pneumoniae', '2025-12-19 15:21:08.121842+00', 'mikrobiologie-mittel-05', '2026-02-03 19:51:09.907698+00', 'Mycoplasma pneumoniae verursacht eine atypische Pneumonie mit trockenem Husten. Ohne Zellwand wirken Beta-Laktame nicht.'),
	('985d6804-4063-4f4f-9cfe-329d303783c5', 'Mikrobiologie', 'Welcher Erreger verursacht Lyme-Borreliose?', '["Borrelia burgdorferi", "Treponema pallidum", "Leptospira interrogans", "Rickettsia rickettsii"]', 'Borrelia burgdorferi', '2025-12-19 15:21:08.121842+00', 'mikrobiologie-schwer-01', '2026-02-03 19:51:09.907698+00', 'Borrelia burgdorferi wird durch Ixodes-Zecken uebertragen. Frueh zeigt sich ein Erythema migrans, spaeter koennen Neuro- oder Gelenksymptome folgen.'),
	('1139f9c1-d5b4-49b8-9ecf-5d53f0da81aa', 'Mikrobiologie', 'Welches Gen vermittelt Methicillinresistenz bei MRSA?', '["mecA", "vanA", "blaCTX-M", "gyrA"]', 'mecA', '2025-12-19 15:21:08.121842+00', 'mikrobiologie-schwer-02', '2026-02-03 19:51:09.907698+00', 'Das mecA-Gen codiert PBP2a, ein veraendertes Penicillin-Bindeprotein. Dadurch sind MRSA gegen viele Beta-Laktam-Antibiotika resistent.'),
	('7666cc94-178e-4d10-9b67-8897cd8a39f7', 'Mikrobiologie', 'Welches Virus besitzt eine Reverse Transkriptase?', '["HIV", "Adenovirus", "HPV", "Parvovirus B19"]', 'HIV', '2025-12-19 15:21:08.121842+00', 'mikrobiologie-schwer-03', '2026-02-03 19:51:09.907698+00', 'HIV ist ein Retrovirus mit Reverse Transkriptase. Es integriert sein Genom und infiziert vor allem CD4-T-Helferzellen.'),
	('fd916b22-a317-44ac-a4ed-36547e3dc78f', 'Mikrobiologie', 'Welcher Erreger verursacht Legionella-Pneumonie?', '["Legionella pneumophila", "Chlamydia trachomatis", "Bordetella pertussis", "Coxiella burnetii"]', 'Legionella pneumophila', '2025-12-19 15:21:08.121842+00', 'mikrobiologie-schwer-04', '2026-02-03 19:51:09.907698+00', 'Legionella pneumophila verbreitet sich ueber Aerosole aus Wasseranlagen. Sie lebt intrazellulaer in Makrophagen und verursacht eine schwere atypische Pneumonie.'),
	('edd73387-2674-4155-ac64-37f828234450', 'Mikrobiologie', 'Welche Bakterien besitzen keine Zellwand?', '["Mycoplasmen", "Staphylokokken", "Streptokokken", "Listerien"]', 'Mycoplasmen', '2025-12-19 15:21:08.121842+00', 'mikrobiologie-schwer-05', '2026-02-03 19:51:09.907698+00', 'Mycoplasmen besitzen keine Zellwand und sind pleomorph. Deshalb wirken Beta-Laktame nicht, und Makrolide sind haeufig Mittel der Wahl.'),
	('c87f4c17-8e3f-4c97-8530-66d75b51440d', 'Chirurgie', 'Welche Struktur muss bei Schilddrüsen-OP besonders geschont werden?', '["N. recurrens", "N. opticus", "N. tibialis", "N. phrenicus"]', 'N. recurrens', '2026-01-30 21:45:58.910706+00', 'chirurgie-extra-2026-03', '2026-03-14 13:27:24.246299+00', 'Der N. recurrens innerviert die Stimmlippenmuskulatur. Wird er bei einer Schilddruesenoperation verletzt, drohen Heiserkeit oder sogar relevante Atemprobleme.'),
	('e36e16bb-1ffc-4096-b716-0ed06d675e52', 'Anatomie', 'Welche Klappe trennt linken Vorhof und linken Ventrikel?', '["Mitralklappe", "Aortenklappe", "Trikuspidalklappe", "Pulmonalklappe"]', 'Mitralklappe', '2026-01-30 21:45:58.767708+00', 'anatomie-herz-01', '2026-03-14 13:27:24.334639+00', 'Mitralklappe ist richtig, weil diese Antwort die medizinische Kernaussage der Frage am besten trifft.'),
	('d837ccc0-3d60-468c-b684-9c6d0eec900e', 'Physiologie', 'Welches Volumen bleibt nach maximaler Ausatmung in der Lunge?', '["Residualvolumen", "Atemzugvolumen", "Vitalkapazität", "Inspiratorisches Reservevolumen"]', 'Residualvolumen', '2026-01-30 21:45:58.767708+00', 'physiologie-lunge-02', '2026-03-14 13:27:24.334639+00', 'Residualvolumen ist richtig, weil diese Antwort die medizinische Kernaussage der Frage am besten trifft.'),
	('11cbe6c6-2e9b-4eaf-9733-874f7b213087', 'Pharmakologie', 'Wie veraendert ein Thiazid die renale Kalziumausscheidung im Urin typischerweise?', '["Die renale Kalziumausscheidung nimmt ab", "Die renale Kalziumausscheidung nimmt deutlich zu", "Die renale Kalziumausscheidung bleibt unveraendert", "Die renale Kalziumausscheidung steigt nur bei Azidose"]', 'Sie nimmt ab', '2026-03-14 22:12:26.645189+00', 'pharmakologie-thiazide-kalzium', '2026-03-14 22:14:57.440317+00', 'Thiazide foerdern die Kalziumrueckresorption im distalen Tubulus. Deshalb sinkt die renale Kalziumausscheidung, was auch ihre Rolle bei kalziumhaltigen Nierensteinen erklaert.'),
	('e1d8c794-dd06-47c2-a9e6-a6b5b8d99126', 'Mikrobiologie', 'Mit welchem malignen Tumor des Gastrointestinaltrakts ist eine Streptococcus-gallolyticus-Bakteriaemie besonders assoziiert?', '["Kolonkarzinom", "Nierenzellkarzinom", "Schilddruesenkarzinom", "Hepatozellulaeres Karzinom"]', 'Kolonkarzinom', '2026-03-14 22:03:54.720926+00', 'mikrobiologie-strep-gallolyticus-kolon', '2026-03-14 22:14:57.440317+00', 'Streptococcus gallolyticus, frueher S. bovis, ist klassisch mit Kolonneoplasien assoziiert. Deshalb sollte bei entsprechender Bakteriaemie oder Endokarditis gezielt nach einem Kolonkarzinom gesucht werden.'),
	('3a92ba10-07e9-43e5-bdec-df6ea5a387c4', 'Anatomie', 'Welcher Hirnabschnitt koordiniert Bewegungen?', '["Kleinhirn", "Thalamus", "Hirnstamm", "Hypothalamus"]', 'Kleinhirn', '2026-01-30 21:45:58.767708+00', 'anatomie-neuro-02', '2026-03-14 13:27:24.334639+00', 'Kleinhirn ist richtig, weil diese Antwort die medizinische Kernaussage der Frage am besten trifft.'),
	('f1b00fa5-8bbd-42e1-9164-aad7a697e7ae', 'Pharmakologie', 'Welcher Gerinnungstest beziehungsweise Laborwert wird zur Kontrolle einer Warfarin-Therapie typischerweise verwendet?', '["INR (International Normalized Ratio)", "aPTT", "Troponin", "D-Dimer"]', 'INR (International Normalized Ratio)', '2026-03-14 22:12:26.645189+00', 'pharmakologie-warfarin-inr', '2026-03-14 22:21:58.413641+00', 'Warfarin beeinflusst die Vitamin-K-abhaengige Bildung mehrerer Gerinnungsfaktoren im extrinsischen System. Deshalb wird die Wirkung klinisch ueber die Prothrombinzeit bzw. den INR-Wert kontrolliert.'),
	('7091d0d1-585a-4ae5-994e-3460b70c813b', 'Physiologie', 'Welche Zellen transportieren Sauerstoff?', '["Erythrozyten", "Leukozyten", "Thrombozyten", "Monozyten"]', 'Erythrozyten', '2026-01-30 21:45:58.767708+00', 'physiologie-haema-01', '2026-03-14 13:27:24.334639+00', 'Diese Antwort ist richtig, weil die genannten Zellen die im Fragetext beschriebene immunologische oder pathologische Rolle haben.'),
	('86a08a46-9a87-4e77-90bc-1e9417800e1b', 'Anatomie', 'Welche Struktur reguliert den Lichteinfall ins Auge?', '["Iris", "Linse", "Netzhaut", "Aderhaut"]', 'Iris', '2026-01-30 21:45:58.767708+00', 'anatomie-oph-01', '2026-03-14 13:27:24.334639+00', 'Diese Antwort ist richtig, weil die genannte Struktur die in der Frage gesuchte anatomische Funktion erfuellt.'),
	('ca6e0b05-de4c-4926-bc22-2d70f5362016', 'Physiologie', 'Welche EKG-Welle repräsentiert die Vorhoferregung?', '["P-Welle", "QRS-Komplex", "T-Welle", "U-Welle"]', 'P-Welle', '2026-01-30 21:45:58.767708+00', 'physiologie-herz-01', '2026-03-14 13:27:24.334639+00', 'Die P-Welle repraesentiert die Depolarisation der Vorhoefe. Erst danach folgt im QRS-Komplex die Erregung der Ventrikel.'),
	('f3327fb0-011c-4933-b4cd-6ccf13e935ee', 'Physiologie', 'Wo findet der Gasaustausch in der Lunge statt?', '["Alveolen", "Bronchien", "Pleura", "Trachea"]', 'Alveolen', '2026-01-30 21:45:58.767708+00', 'physiologie-lunge-01', '2026-03-14 13:27:24.334639+00', 'Der Gasaustausch findet in den Alveolen statt, weil dort eine extrem duenne Blut-Luft-Schranke besteht. So kann Sauerstoff ins Blut diffundieren und Kohlendioxid in die Ausatemluft uebertreten.'),
	('8ed37ab3-18aa-453f-a953-6e7dbb83245f', 'Anatomie', 'Welcher Muskel ist der wichtigste Atemmuskel?', '["Zwerchfell", "Interkostalmuskeln", "M. sternocleidomastoideus", "Bauchmuskeln"]', 'Zwerchfell', '2026-01-30 21:45:58.767708+00', 'anatomie-lunge-01', '2026-03-14 13:27:24.334639+00', 'Das Zwerchfell ist der wichtigste Atemmuskel, weil seine Kontraktion den Thorax nach kaudal erweitert. Dadurch sinkt der intrathorakale Druck und Luft stroemt in die Lunge.'),
	('f7ab05f5-725e-4dea-a504-8a103329a8cc', 'Physiologie', 'Wo findet die Ultrafiltration in der Niere statt?', '["Glomerulus", "Henle-Schleife", "Sammelrohr", "Distaler Tubulus"]', 'Glomerulus', '2026-01-30 21:45:58.767708+00', 'physiologie-niere-01', '2026-03-14 13:27:24.334639+00', 'Die Ultrafiltration findet im Glomerulus statt, wo Blut durch die Filtrationsbarriere in den Kapselraum gepresst wird. So entsteht der Primaerharn.'),
	('7aaf5d7f-6274-4781-9b68-ef8af0b1b2c0', 'Physiologie', 'Welche Struktur ist entscheidend für die Gegenstrommultiplikation?', '["Henle-Schleife", "Bowman-Kapsel", "Proximaler Tubulus", "Glomerulus"]', 'Henle-Schleife', '2026-01-30 21:45:58.767708+00', 'physiologie-niere-03', '2026-03-14 13:27:24.334639+00', 'Die Henle-Schleife ist entscheidend fuer die Gegenstrommultiplikation, weil ab- und aufsteigender Schenkel unterschiedliche Permeabilitaeten fuer Wasser und Salz besitzen. Dadurch entsteht der osmotische Gradient im Nierenmark.'),
	('7160d588-e7b7-45d8-9018-1d1ab91b406a', 'Pathologie', 'Welches Enzym ist typisch erhöht bei cholestatischem Leberschaden?', '["Alkalische Phosphatase", "Amylase", "Troponin", "CK-MB"]', 'Alkalische Phosphatase', '2026-01-30 21:45:58.767708+00', 'pathologie-leber-01', '2026-03-14 13:27:24.334639+00', 'Die alkalische Phosphatase steigt bei cholestatischem Leberschaden an, weil sie vor allem im Bereich der Gallenwege vorkommt. Eine Cholestase fuehrt deshalb typischerweise zu erhoehten ALP-Werten.'),
	('09f5f514-aae2-4788-b3c1-f3c198fc4cbe', 'Physiologie', 'Welches Toxin wird in der Leber zu Harnstoff entgiftet?', '["Ammoniak", "Laktat", "Glukose", "Bilirubin"]', 'Ammoniak', '2026-01-30 21:45:58.767708+00', 'physiologie-leber-02', '2026-03-14 13:27:24.334639+00', 'Ammoniak wird in der Leber im Harnstoffzyklus entgiftet. Das ist wichtig, weil freies Ammoniak neurotoxisch ist und daher rasch in besser ausscheidbaren Harnstoff umgewandelt werden muss.'),
	('d25210b9-a523-49ca-b829-e65d753cbe69', 'Anatomie', 'Welcher Hirnnerv innerviert den M. rectus lateralis?', '["N. abducens (VI)", "N. oculomotorius (III)", "N. trochlearis (IV)", "N. trigeminus (V)"]', 'N. abducens (VI)', '2026-01-30 21:45:58.767708+00', 'anatomie-neuro-01', '2026-03-14 13:27:24.334639+00', 'Der N. abducens innerviert den M. rectus lateralis und ermoeglicht damit die Abduktion des Auges. Bei einer Laesion kann das betroffene Auge nicht mehr richtig nach aussen bewegt werden.'),
	('f9b239c6-b9ff-4aca-bb3d-78ad76eced2b', 'Physiologie', 'Welche Drüsenstruktur produziert TSH?', '["Adenohypophyse", "Neurohypophyse", "Nebennierenmark", "Schilddrüse"]', 'Adenohypophyse', '2026-01-30 21:45:58.767708+00', 'physiologie-endo-01', '2026-03-14 13:27:24.334639+00', 'TSH wird in der Adenohypophyse gebildet. Von dort stimuliert es die Schilddruese zur Bildung und Freisetzung von T3 und T4.'),
	('d763b69b-0d5a-4ba2-b684-1f6de6520e7d', 'Physiologie', 'Welches Hormon wird in der Nebennierenrinde gebildet und erhöht den Blutdruck?', '["Aldosteron", "Adrenalin", "Insulin", "Glukagon"]', 'Aldosteron', '2026-01-30 21:45:58.767708+00', 'physiologie-endo-02', '2026-03-14 13:27:24.334639+00', 'Aldosteron wird in der Zona glomerulosa der Nebennierenrinde gebildet. Es steigert die Natrium- und Wasserretention in der Niere und kann so den Blutdruck erhoehen.'),
	('46f06b2d-af16-4436-9ec3-13e69bf6a3db', 'Physiologie', 'Welches Hormon fördert die Aufnahme von Glukose in Zellen?', '["Insulin", "Glukagon", "Cortisol", "Adrenalin"]', 'Insulin', '2026-01-30 21:45:58.767708+00', 'physiologie-endo-03', '2026-03-14 13:27:24.334639+00', 'Insulin foerdert die Aufnahme von Glukose in Zellen, vor allem in Muskel- und Fettgewebe. Dazu bewirkt es unter anderem die Einlagerung von GLUT4 in die Zellmembran.'),
	('5300bc3e-1479-4565-a1f2-ce0910cc9ead', 'Anatomie', 'Welche Struktur speichert Galle?', '["Gallenblase", "Pankreas", "Milz", "Duodenum"]', 'Gallenblase', '2026-01-30 21:45:58.767708+00', 'anatomie-gastro-01', '2026-03-14 13:27:24.334639+00', 'Die Gallenblase speichert und konzentriert die in der Leber gebildete Galle zwischen den Mahlzeiten. Nach Nahrungsaufnahme wird sie in das Duodenum abgegeben.'),
	('2a584990-6f61-4085-b124-3186331836c5', 'Mikrobiologie', 'Welcher Erreger verursacht häufig peptische Ulzera?', '["Helicobacter pylori", "E. coli", "Salmonella enterica", "Campylobacter jejuni"]', 'Helicobacter pylori', '2026-01-30 21:45:58.767708+00', 'mikrobiologie-gastro-01', '2026-03-14 13:27:24.334639+00', 'Helicobacter pylori kolonisiert die Magenschleimhaut und foerdert dort chronische Entzuendung. Dadurch entstehen haeufig Gastritis und peptische Ulzera.'),
	('f87c115b-fc74-4ab9-aada-ed867985b22c', 'Physiologie', 'Wo wird Vitamin B12 hauptsächlich resorbiert?', '["Terminales Ileum", "Duodenum", "Jejunum", "Colon"]', 'Terminales Ileum', '2026-01-30 21:45:58.767708+00', 'physiologie-gastro-01', '2026-03-14 13:27:24.334639+00', 'Vitamin B12 wird hauptsaechlich im terminalen Ileum resorbiert. Voraussetzung dafuer ist die Bindung an Intrinsic Factor aus dem Magen.'),
	('ce66991c-6ed9-47d6-ac6d-b6221339e9ba', 'Physiologie', 'Welche Gerinnungszeit prüft vor allem die extrinsische Kaskade?', '["Quick/INR", "aPTT", "Thrombinzeit", "Blutungszeit"]', 'Quick/INR', '2026-01-30 21:45:58.767708+00', 'physiologie-haema-02', '2026-03-14 13:27:24.334639+00', 'Quick/INR prueft vor allem die extrinsische Gerinnungskaskade, insbesondere den Faktor VII. Deshalb wird der Wert auch zur Kontrolle einer Vitamin-K-Antagonisten-Therapie genutzt.'),
	('be5b726d-179d-495d-abb2-04367dab6a67', 'Pathologie', 'Welches Vitamin ist bei perniziöser Anämie vermindert?', '["Vitamin B12", "Vitamin C", "Vitamin D", "Vitamin K"]', 'Vitamin B12', '2026-01-30 21:45:58.767708+00', 'pathologie-haema-01', '2026-03-14 13:27:24.334639+00', 'Bei pernizioeser Anaemie ist Vitamin B12 vermindert, weil durch Intrinsic-Factor-Mangel die Aufnahme im terminalen Ileum gestoert ist. Dadurch entsteht eine megaloblaestaere Anaemie.'),
	('0681a04f-b4ee-42d7-bc83-00812d3d089b', 'Pathologie', 'Welcher UV-Bereich verursacht Sonnenbrand am ehesten?', '["UVB", "UVA", "UVC", "Infrarot"]', 'UVB', '2026-01-30 21:45:58.767708+00', 'pathologie-derm-01', '2026-03-14 13:27:24.334639+00', 'UVB verursacht Sonnenbrand am ehesten, weil diese Strahlung vor allem die Epidermis erreicht und dort direkte DNA-Schaeden ausloest. UVA dringt tiefer ein, ist aber weniger typisch fuer den akuten Sonnenbrand.'),
	('4c1f4dfd-4c09-4e5f-adc3-5b88089a4bc8', 'Anatomie', 'Wie heisst die oberste Hautschicht?', '["Epidermis", "Dermis", "Subkutis", "Faszie"]', 'Epidermis', '2026-01-30 21:45:58.767708+00', 'anatomie-derm-01', '2026-03-14 13:27:24.334639+00', 'Die Epidermis ist die oberste Hautschicht und bildet die aeussere Barriere des Koerpers. Sie schuetzt vor Keimen, Austrocknung und mechanischen Reizen.'),
	('9a11e1f0-864d-48b8-9b1c-843dcdbd1846', 'Mikrobiologie', 'Welcher Erreger verursacht häufig Impetigo contagiosa?', '["Staphylococcus aureus", "Escherichia coli", "Candida albicans", "Mycoplasma pneumoniae"]', 'Staphylococcus aureus', '2026-01-30 21:45:58.767708+00', 'mikrobiologie-derm-01', '2026-03-14 13:27:24.334639+00', 'Staphylococcus aureus ist ein haeufiger Erreger der Impetigo contagiosa. Der Keim verursacht eine oberflaechliche eitrige Hautinfektion mit typischen honiggelben Krusten.'),
	('d3a4e2d8-a72c-4de8-82a6-17479d4728dc', 'Anatomie', 'Welche Struktur sorgt für das scharfe Sehen?', '["Fovea centralis", "Papille", "Glaskörper", "Ziliarkörper"]', 'Fovea centralis', '2026-01-30 21:45:58.767708+00', 'anatomie-oph-02', '2026-03-14 13:27:24.334639+00', 'Die Fovea centralis ist der Ort des schaerfsten Sehens, weil dort die Dichte der Zapfen am hoechsten ist. Sie ist fuer hochaufgeloestes Farb- und Detailsehen entscheidend.'),
	('f5a6e769-9427-4832-a8f0-8974da8aeadf', 'Pathologie', 'Welcher Druck ist bei Glaukom typischerweise erhöht?', '["Augeninnendruck", "Blutdruck", "Liquordruck", "Pulsdruck"]', 'Augeninnendruck', '2026-01-30 21:45:58.767708+00', 'pathologie-oph-01', '2026-03-14 13:27:24.334639+00', 'Beim Glaukom ist der Augeninnendruck haeufig erhoeht, was den Sehnerv langfristig schaedigen kann. Unbehandelt drohen Gesichtsfeldausfaelle bis zur Erblindung.'),
	('49542394-e9f8-4473-ac36-f43804b0db2c', 'Anatomie', 'Durch welches Foramen der Schaedelbasis verlaesst der N. mandibularis (V3) die mittlere Schaedelgrube?', '["Foramen ovale", "Foramen rotundum", "Foramen jugulare", "Foramen spinosum"]', 'Foramen ovale', '2026-03-14 22:03:54.475151+00', 'anatomie-v3-foramen-ovale', '2026-03-14 22:18:29.584446+00', 'Der dritte Ast des N. trigeminus zieht durch das Foramen ovale. Er fuehrt sensible Fasern fuer den Unterkiefer und motorische Fasern fuer die Kaumuskulatur.'),
	('4f212f10-cfc7-437d-ba30-05a0f6c93309', 'Physiologie', 'Welcher Nephronabschnitt resorbiert unter physiologischen Bedingungen den groessten Anteil des filtrierten Natriums?', '["Proximaler Tubulus", "Henle-Schleife", "Distaler Tubulus", "Sammelrohr"]', 'Proximaler Tubulus', '2026-03-14 22:03:54.475151+00', 'physiologie-proximaler-tubulus-natrium', '2026-03-14 22:18:29.584446+00', 'Im proximalen Tubulus werden etwa zwei Drittel des filtrierten Natriums rueckresorbiert. Dieser Abschnitt uebernimmt auch einen grossen Teil der Wasser-, Bikarbonat- und Glukoserueckresorption.'),
	('5077f0e8-7c21-4ac4-9199-2080b2d2f292', 'Pathologie', 'Welche Zellart gilt histologisch als Leitzelle des klassischen Hodgkin-Lymphoms?', '["Reed-Sternberg-Zellen", "Plasmazellen", "Schwann-Zellen", "Kupffer-Zellen"]', 'Reed-Sternberg-Zellen', '2026-03-14 22:03:54.475151+00', 'pathologie-hodgkin-reed-sternberg', '2026-03-14 22:18:29.584446+00', 'Das klassische Hodgkin-Lymphom ist durch grosse mehrkernige Reed-Sternberg-Zellen gekennzeichnet. Sie liegen meist in einem entzuendlichen Zellhintergrund und exprimieren typischerweise CD15 und CD30.'),
	('02ba3136-4e3e-4e5d-b9b6-36513de00a71', 'Mikrobiologie', 'Welcher Erreger verursacht nach Breitspektrum-Antibiotikatherapie klassisch eine pseudomembranoese Kolitis?', '["Clostridioides difficile", "Salmonella enterica", "Helicobacter pylori", "Campylobacter jejuni"]', 'Clostridioides difficile', '2026-03-14 22:03:54.475151+00', 'mikrobiologie-cdiff-pseudomembranoese-kolitis', '2026-03-14 22:18:29.584446+00', 'Clostridioides difficile kann sich nach Stoerung der Darmflora durch Antibiotika stark vermehren. Seine Toxine fuehren zu waessriger Diarrhoe und pseudomembranoeser Kolitis.'),
	('0cd5e041-283f-446d-8dd1-2872297141ed', 'Biochemie', 'Welches Enzym katalysiert in der Glykolyse die Umwandlung von Fructose-6-phosphat zu Fructose-1,6-bisphosphat?', '["Phosphofructokinase-1", "Hexokinase", "Pyruvatkinase", "Glukose-6-phosphat-Dehydrogenase"]', 'Phosphofructokinase-1', '2026-03-14 22:03:54.475151+00', 'biochemie-pfk1-glykolyse', '2026-03-14 22:18:29.584446+00', 'Die Phosphofructokinase-1 ist ein zentrales Regulationsenzym der Glykolyse. Der Schritt ist praktisch irreversibel und wird unter anderem durch ATP, AMP und Fructose-2,6-bisphosphat reguliert.'),
	('81367449-9602-42a1-94d5-f7221603ddaa', 'Genetik', 'Welches DNA-Reparatursystem ist beim Lynch-Syndrom typischerweise ausgefallen?', '["Mismatch-Repair-System", "Basenexzisionsreparatur", "Nicht-homologe Endverknuepfung", "Nukleotidexzisionsreparatur"]', 'Mismatch-Repair-System', '2026-03-14 22:03:54.475151+00', 'genetik-lynch-mismatch-repair', '2026-03-14 22:18:29.584446+00', 'Beim Lynch-Syndrom sind meist Gene des DNA-Mismatch-Repair-Systems wie MLH1, MSH2, MSH6 oder PMS2 betroffen. Der Defekt fuehrt zu Mikrosatelliteninstabilitaet und erhoehtem Karzinomrisiko.'),
	('fc8d038f-ffa4-4832-8c3f-7b12a71111aa', 'Radiologie', 'Welcher Befund im Thoraxroentgen spricht bei akutem klinischem Verdacht am staerksten fuer einen Spannungspneumothorax?', '["Mediastinalverlagerung zur Gegenseite", "Beidseitige Pleuraerguesse", "Verkalkte Pleuraplaques", "Verbreiterter Hilus beidseits"]', 'Mediastinalverlagerung zur Gegenseite', '2026-03-14 22:03:54.475151+00', 'radiologie-spannungspneumothorax-mediastinalverlagerung', '2026-03-14 22:18:29.584446+00', 'Beim Spannungspneumothorax fuehrt der steigende intrathorakale Druck zu einer Verlagerung des Mediastinums auf die Gegenseite. Das ist ein Warnzeichen fuer eine haeufig sofort behandlungsbeduerftige Druckproblematik.'),
	('55a2b203-7308-4855-9186-478183d57cb9', 'Chirurgie', 'Welcher Nerv muss bei der Thyreoidektomie geschont werden, um eine postoperative Stimmlippenparese mit Heiserkeit zu vermeiden?', '["N. laryngeus recurrens", "N. phrenicus", "N. glossopharyngeus", "N. hypoglossus"]', 'N. laryngeus recurrens', '2026-03-14 22:03:54.475151+00', 'chirurgie-thyreoidektomie-recurrens', '2026-03-14 22:18:29.584446+00', 'Der N. laryngeus recurrens innerviert den Grossteil der inneren Kehlkopfmuskulatur. Eine Laesion kann zu Heiserkeit, Stimmbandparese und bei beidseitiger Schaedigung zu relevanter Atemwegsproblematik fuehren.'),
	('690fa355-d0fb-40df-8ad2-16233be54cb6', 'Pathologie', 'Welcher Serumtumormarker ist beim hepatozellulaeren Karzinom klassisch erhoeht?', '["Alpha-Fetoprotein (AFP)", "CA 19-9", "PSA", "Calcitonin"]', 'Alpha-Fetoprotein (AFP)', '2026-03-14 22:03:54.475151+00', 'pathologie-hcc-afp', '2026-03-14 22:18:29.584446+00', 'AFP kann beim hepatozellulaeren Karzinom erhoeht sein und wird zusammen mit Bildgebung und klinischem Kontext bewertet. Ein normaler AFP-Wert schliesst das HCC jedoch nicht sicher aus.'),
	('bb3e4c15-cea0-4bf6-8149-36c77014506c', 'Chirurgie', 'Welcher klinische Score wird bei Erwachsenen haeufig zur Einschaetzung einer akuten Appendizitis verwendet?', '["Alvarado-Score", "Child-Pugh-Score", "MELD-Score", "HAS-BLED-Score"]', 'Alvarado-Score', '2026-03-14 22:03:54.475151+00', 'chirurgie-alvarado-appendizitis', '2026-03-14 22:18:29.584446+00', 'Der Alvarado-Score kombiniert Symptome, klinische Befunde und Laborparameter wie Leukozytose. Er hilft bei der Risikostratifizierung, ersetzt aber nicht die klinische Gesamteinschaetzung.'),
	('7e85f189-6ebb-4165-9bd7-462930e7db9f', 'Anatomie', 'Durch welches Foramen der Schaedelbasis tritt die A. meningea media in die Schaedelhoehle ein?', '["Foramen spinosum", "Foramen ovale", "Foramen rotundum", "Canalis caroticus"]', 'Foramen spinosum', '2026-03-14 22:03:54.627029+00', 'anatomie-foramen-spinosum-a-meningea-media', '2026-03-14 22:18:29.584446+00', 'Die A. meningea media zieht durch das Foramen spinosum. Sie versorgt grosse Teile der Dura und ist klinisch wichtig, weil ihre Ruptur ein epidurales Haematom verursachen kann.'),
	('70446a7b-547b-4a47-98f4-ce2556ab5d27', 'Mikrobiologie', 'Welcher ureasepositive Erreger ist klassisch mit Struvit- und Hirschgeweihsteinen assoziiert?', '["Proteus mirabilis", "Escherichia coli", "Staphylococcus epidermidis", "Enterococcus faecium"]', 'Proteus mirabilis', '2026-03-14 22:03:54.627029+00', 'mikrobiologie-proteus-struvit', '2026-03-14 22:18:29.584446+00', 'Proteus mirabilis bildet Urease und alkalisiert damit den Urin. Das foerdert die Ausfaellung von Magnesium-Ammonium-Phosphat und damit die Bildung von Struvit- beziehungsweise Hirschgeweihsteinen.'),
	('0c04d311-e762-4046-921f-6ea4ce58105a', 'Mikrobiologie', 'Welcher Erreger einer atypischen Pneumonie ist klassisch mit kalten Agglutininen assoziiert?', '["Mycoplasma pneumoniae", "Legionella pneumophila", "Chlamydia psittaci", "Klebsiella pneumoniae"]', 'Mycoplasma pneumoniae', '2026-03-14 22:03:54.627029+00', 'mikrobiologie-mycoplasma-kalte-agglutinine', '2026-03-14 22:18:29.584446+00', 'Mycoplasma pneumoniae verursacht atypische Pneumonien und kann die Bildung kalter Agglutinine ausloesen. Diese Eigenschaft ist ein klassischer Pruefstein in der Differenzialdiagnose.'),
	('9d5dfb20-0957-489e-9513-c61ef41f2080', 'Immunologie', 'Welcher Typ der Hypersensitivitaetsreaktion liegt dem Goodpasture-Syndrom zugrunde?', '["Typ-II-Hypersensitivitaet", "Typ-I-Hypersensitivitaet", "Typ-III-Hypersensitivitaet", "Typ-IV-Hypersensitivitaet"]', 'Typ-II-Hypersensitivitaet', '2026-03-14 22:03:54.627029+00', 'immunologie-goodpasture-typ2', '2026-03-14 22:18:29.584446+00', 'Beim Goodpasture-Syndrom richten sich Antikoerper direkt gegen Bestandteile der Basalmembran. Das entspricht einer antikoerpervermittelten Typ-II-Hypersensitivitaet.'),
	('5a2fa77a-161f-4dbd-a25c-86ebbd156721', 'Anatomie', 'Welche Arterie ist bei einer Fraktur im Bereich des Pterions besonders gefaehrdet?', '["A. meningea media", "A. cerebri anterior", "A. ophthalmica", "A. vertebralis"]', 'A. meningea media', '2026-03-14 22:03:54.720926+00', 'anatomie-pterion-meningea-media', '2026-03-14 22:18:29.584446+00', 'Im Bereich des Pterions verlaeuft die A. meningea media dicht an der Innenseite des Schaedels. Eine Fraktur dort kann die Arterie verletzen und ein epidurales Haematom ausloesen.'),
	('b66dca61-17aa-4006-8c16-0943fb05b5e8', 'Anatomie', 'Welcher Nerv verlaeuft zusammen mit den Beugesehnen durch den Carpaltunnel?', '["N. medianus", "N. ulnaris", "N. radialis", "N. axillaris"]', 'N. medianus', '2026-03-14 22:03:54.720926+00', 'anatomie-carpaltunnel-nerv', '2026-03-14 22:18:29.584446+00', 'Der N. medianus zieht gemeinsam mit den Beugesehnen durch den Carpaltunnel. Genau deshalb fuehrt ein Carpaltunnelsyndrom typischerweise zu medianusbetonten Sensibilitaetsstoerungen und Thenarschwaeche.'),
	('cbdd4417-99cc-472e-a988-dd6382707694', 'Pathologie', 'Welcher histopathologische Befund spricht im Vergleich zur Colitis ulcerosa fuer Morbus Crohn?', '["Transmurale Entzuendung", "Kontinuierliche Mukosalaesion nur im Rektum", "Ausschliesslich oberflaechliche Mukositis", "Pseudopolypen ohne Wandbeteiligung"]', 'Transmurale Entzuendung', '2026-03-14 22:03:54.720926+00', 'pathologie-crohn-transmural', '2026-03-14 22:18:29.584446+00', 'Morbus Crohn betrifft typischerweise die gesamte Darmwand und fuehrt daher zu transmuraler Entzuendung. Genau diese tiefe Wandbeteiligung erklaert Komplikationen wie Fisteln und Strikturen.'),
	('5539f839-d418-4800-afd0-5ba6cf118f81', 'Mikrobiologie', 'Welcher gramnegative Erreger ist oxidasepositiv und produziert haeufig blaugruene Pigmente?', '["Pseudomonas aeruginosa", "Escherichia coli", "Klebsiella pneumoniae", "Shigella sonnei"]', 'Pseudomonas aeruginosa', '2026-03-14 22:03:54.720926+00', 'mikrobiologie-pseudomonas-oxidase', '2026-03-14 22:18:29.584446+00', 'Pseudomonas aeruginosa ist oxidasepositiv und kann Pigmente wie Pyocyanin bilden, die blaugruene Faerbung verursachen. Diese Kombination ist ein klassischer Laborhinweis auf den Erreger.'),
	('90f377ff-54e5-4b29-96e1-0ad5797fb30b', 'Biochemie', 'Der Mangel welches Vitamins beeintraechtigt den Pyruvatdehydrogenase-Komplex besonders?', '["Vitamin-B1-Mangel", "Vitamin-B12-Mangel", "Vitamin-C-Mangel", "Vitamin-D-Mangel"]', 'Vitamin-B1-Mangel', '2026-03-14 22:03:54.720926+00', 'biochemie-pdh-thiamin', '2026-03-14 22:18:29.584446+00', 'Der Pyruvatdehydrogenase-Komplex benoetigt Thiaminpyrophosphat als Kofaktor. Daher stoert ein Vitamin-B1-Mangel diesen Komplex und foerdert Laktatanstieg sowie Energiemangel.'),
	('e6733af6-0fae-4e44-b06b-1c501b46972f', 'Pharmakologie', 'Welche Rezeptorfamilie blockiert Atropin kompetitiv?', '["Muskarinische Acetylcholinrezeptoren", "Nikotinische Acetylcholinrezeptoren", "Beta-2-Rezeptoren", "Dopamin-D2-Rezeptoren"]', 'Muskarinische Acetylcholinrezeptoren', '2026-03-14 22:12:26.645189+00', 'pharmakologie-atropin-muskarin', '2026-03-14 22:18:29.584446+00', 'Atropin wirkt als kompetitiver Antagonist an muskarinischen Acetylcholinrezeptoren. Genau dadurch steigen Herzfrequenz und Pupillenweite, waehrend parasympathische Wirkungen gehemmt werden.'),
	('212f5df4-c8b6-4d00-b49f-49d84237adf3', 'Immunologie', 'Welches Komplementfragment ist besonders stark chemotaktisch fuer neutrophile Granulozyten?', '["C5a-Komplementfragment", "C3b als Opsonin", "C1q", "Membranangriffskomplex (MAC)"]', 'C5a-Komplementfragment', '2026-03-14 22:03:54.720926+00', 'immunologie-c5a-chemotaxis', '2026-03-14 22:21:58.413641+00', 'C5a ist ein potentes chemotaktisches und proinflammatorisches Komplementfragment. Gerade diese Eigenschaft lenkt neutrophile Granulozyten an den Ort der Entzuendung.'),
	('d9ec3875-af74-439e-8a36-effdb3e99279', 'Immunologie', 'Welches Oberflaechenmolekuel dient HIV als primaerer Rezeptor auf CD4-positiven T-Helferzellen?', '["CD4-Rezeptor", "CD8-Rezeptor", "CD16", "CD20"]', 'CD4-Rezeptor', '2026-03-14 22:03:54.720926+00', 'immunologie-hiv-cd4', '2026-03-14 22:21:58.413641+00', 'HIV bindet zunaechst an CD4 auf T-Helferzellen und nutzt anschliessend Korezeptoren wie CCR5 oder CXCR4 fuer den Eintritt. CD4 ist daher der primaere Oberflaechenrezeptor.'),
	('8128996b-00cc-40af-b08d-e20bc87d1eed', 'Radiologie', 'Welche Form zeigt ein subdurales Haematom typischerweise im kranialen CT?', '["sichelfoermig entlang der Hemisphaerenkonvexitaet", "linsenfoermig bzw. bikonvex", "ringfoermig", "sternfoermig"]', 'sichelfoermig entlang der Hemisphaerenkonvexitaet', '2026-03-14 22:03:54.720926+00', 'radiologie-subdural-crescent', '2026-03-14 22:21:58.413641+00', 'Ein subdurales Haematom breitet sich entlang der Hirnoberflaeche aus und erscheint deshalb meist sichelfoermig. Im Gegensatz dazu ist das epidurale Haematom typischerweise linsenfoermig begrenzt.'),
	('ea56021b-c067-4ad2-845f-a3559ef5100e', 'Anatomie', 'In welchen Venenwinkel muendet der Ductus thoracicus beim Erwachsenen typischerweise?', '["linker Venenwinkel (V. jugularis interna sinistra + V. subclavia sinistra)", "rechter Venenwinkel", "V. cava superior", "V. azygos"]', 'linker Venenwinkel (V. jugularis interna sinistra + V. subclavia sinistra)', '2026-03-14 22:12:26.645189+00', 'anatomie-ductus-thoracicus-venenwinkel', '2026-03-14 22:21:58.413641+00', 'Der Ductus thoracicus endet meist am linken Venenwinkel, also am Uebergang von V. jugularis interna sinistra und V. subclavia sinistra. Dadurch gelangt die Lymphe aus dem groessten Teil des Koerpers wieder in den venoesen Kreislauf.'),
	('a1b14748-85ef-43a1-9474-ca78e486aaa6', 'Anatomie', 'Auf Hoehe welchen Wirbelkoerpers durchtritt die Aorta den Hiatus aorticus des Zwerchfells?', '["Th12 auf Hoehe des Hiatus aorticus", "Th8 auf Hoehe des Foramen venae cavae", "Th10 auf Hoehe des Hiatus oesophageus", "L1"]', 'Th12 auf Hoehe des Hiatus aorticus', '2026-03-14 22:12:26.645189+00', 'anatomie-hiatus-aorticus-t12', '2026-03-14 22:21:58.413641+00', 'Die Aorta zieht durch den Hiatus aorticus auf Hoehe Th12. Die bekannten Zwerchfelloeffnungen lauten damit vereinfacht: V. cava inferior auf Th8, Oesophagus auf Th10, Aorta auf Th12.'),
	('a6c11111-3d4e-4bcd-a474-9f292f46971f', 'Anatomie', 'Welche der folgenden Strukturen gehoert zur Portal-Trias im Ligamentum hepatoduodenale?', '["V. portae als Bestandteil der Portal-Trias", "V. hepatica", "A. mesenterica superior", "V. cava inferior"]', 'V. portae als Bestandteil der Portal-Trias', '2026-03-14 22:12:26.645189+00', 'anatomie-ligamentum-hepatoduodenale', '2026-03-14 22:21:58.413641+00', 'Im Ligamentum hepatoduodenale verlaeuft die Portal-Trias aus V. portae, A. hepatica propria und Ductus choledochus. Die V. hepaticae muenden dagegen direkt in die V. cava inferior und gehoeren nicht dazu.'),
	('d8a8aa88-18aa-436c-9408-9fce18ebbc27', 'Pathologie', 'Welche Infektion ist histologisch klassisch mit verkaesenden Granulomen assoziiert?', '["Tuberkulose", "Morbus Crohn", "Colitis ulcerosa", "systemischer Lupus erythematodes (SLE)"]', 'Tuberkulose', '2026-03-14 22:12:26.645189+00', 'pathologie-verkaseungsnekrose-tuberkulose', '2026-03-14 22:21:58.413641+00', 'Verkaesende Granulome sind histologisch typisch fuer die Tuberkulose. Die Kombination aus Granulombildung und zentraler Kaesenekrose verknuepft den Befund direkt mit dieser Infektion.'),
	('bd6f3ff5-a5b9-4748-92d7-0123492878ab', 'Pharmakologie', 'Welchen aktivierten Gerinnungsfaktor hemmt Apixaban direkt?', '["aktivierter Faktor X (Faktor Xa)", "Thrombin (Faktor IIa)", "Faktor VIII", "Fibrinogen"]', 'aktivierter Faktor X (Faktor Xa)', '2026-03-14 22:03:54.475151+00', 'pharmakologie-apixaban-faktor-xa', '2026-03-14 22:21:58.413641+00', 'Apixaban ist ein direkter Xa-Hemmer. Durch die Blockade von Faktor Xa wird die Umwandlung von Prothrombin in Thrombin vermindert und damit die Gerinnungskaskade gebremst.'),
	('6ee47597-da0b-4e10-b932-17732b830d13', 'Immunologie', 'Welcher Toll-like-Rezeptor erkennt Lipopolysaccharid gramnegativer Bakterien?', '["Toll-like-Rezeptor 4 (TLR4)", "Toll-like-Rezeptor 2 (TLR2)", "Toll-like-Rezeptor 3 (TLR3)", "Toll-like-Rezeptor 5 (TLR5)"]', 'Toll-like-Rezeptor 4 (TLR4)', '2026-03-14 22:03:54.475151+00', 'immunologie-tlr4-lps', '2026-03-14 22:21:58.413641+00', 'TLR4 erkennt LPS von gramnegativen Bakterien und aktiviert ueber angeborene Immunantworten die Freisetzung proinflammatorischer Zytokine. TLR5 erkennt dagegen vor allem Flagellin.'),
	('8091b1e4-0f3e-4330-9d9c-c2aec56fd0a8', 'Physiologie', 'Welcher adrenerge Rezeptor vermittelt den positiven chronotropen Effekt von Noradrenalin am Sinusknoten?', '["beta1-adrenerger Rezeptor", "alpha1-adrenerger Rezeptor", "beta2-adrenerger Rezeptor", "muskarinischer M2-Rezeptor"]', 'beta1-adrenerger Rezeptor', '2026-03-14 22:03:54.475151+00', 'physiologie-beta1-herzfrequenz', '2026-03-14 22:21:58.413641+00', 'Noradrenalin steigert ueber Beta-1-Rezeptoren an Sinus- und AV-Knoten Herzfrequenz und Erregungsleitung. M2-Rezeptoren vermitteln dagegen parasympathisch eine Verlangsamung.'),
	('518c77ed-99b2-4200-b4d2-21f2d907d858', 'Biochemie', 'Welches Lipoprotein transportiert Cholesterin vor allem von der Leber in periphere Gewebe?', '["LDL (Low-density-Lipoprotein)", "HDL (High-density-Lipoprotein)", "Chylomikron", "Albumin"]', 'LDL (Low-density-Lipoprotein)', '2026-03-14 22:03:54.475151+00', 'biochemie-ldl-cholesterintransport', '2026-03-14 22:21:58.413641+00', 'LDL liefert Cholesterin an periphere Gewebe und spielt eine zentrale Rolle in der Atherosklerose. HDL ist eher am Ruecktransport von Cholesterin zur Leber beteiligt.'),
	('101d5d91-6db3-4595-b84c-fc31dc7cb23f', 'Radiologie', 'In welcher Kontrastmittelphase der CT zeigt ein hepatozellulaeres Karzinom klassisch ein fruehes hypervaskulaeres Enhancement?', '["arterielle Kontrastmittelphase", "native Phase ohne Kontrastmittel", "portovenoese Phase", "spaetvenoeser Scan"]', 'arterielle Kontrastmittelphase', '2026-03-14 22:03:54.475151+00', 'radiologie-hcc-arterielle-phase', '2026-03-14 22:21:58.413641+00', 'Das hepatozellulaere Karzinom zeigt haeufig ein starkes Enhancement in der arteriellen Phase und ein Washout in spaeteren Phasen. Dieses Kontrastverhalten ist radiologisch sehr typisch.'),
	('93d86602-31d3-4f0d-b7b0-905d8c3c95bb', 'Pharmakologie', 'Welches Medikament wird in der Akutmedizin zur raschen Aufhebung einer Opioidwirkung eingesetzt?', '["Naloxon als Opioidantagonist", "Flumazenil als Benzodiazepinantagonist", "Atropin", "N-Acetylcystein"]', 'Naloxon', '2026-03-14 22:03:54.627029+00', 'pharmakologie-naloxon-opioid', '2026-03-14 22:21:58.413641+00', 'Naloxon ist ein kompetitiver Opioidrezeptor-Antagonist und hebt die atemdepressive Wirkung von Opioiden rasch auf. Deshalb ist es das Mittel der Wahl bei Opioidueberdosierung.'),
	('0797d7f3-4340-4dc0-8e8f-addd8c948b4d', 'Biochemie', 'Welches Enzym ist das geschwindigkeitsbestimmende Enzym des Harnstoffzyklus?', '["Carbamoylphosphat-Synthetase I (CPS1)", "Arginase", "Ornithin-Transcarbamylase", "Pyruvat-Carboxylase"]', 'Carbamoylphosphat-Synthetase I (CPS1)', '2026-03-14 22:03:54.627029+00', 'biochemie-harnstoffzyklus-cps1', '2026-03-14 22:21:58.413641+00', 'Die Carbamoylphosphat-Synthetase I katalysiert den ersten und geschwindigkeitsbestimmenden Schritt des Harnstoffzyklus in den Mitochondrien. Sie benoetigt N-Acetylglutamat als Aktivator.'),
	('c80430ad-08f1-4e7b-90cc-cd6627a43593', 'Biochemie', 'Welcher mobile Elektronentraeger transportiert Elektronen von Komplex I und II zu Komplex III der Atmungskette?', '["Coenzym Q (Ubichinon)", "Cytochrom c", "NADH", "Succinat"]', 'Coenzym Q (Ubichinon)', '2026-03-14 22:03:54.627029+00', 'biochemie-elektronentransport-coenzym-q', '2026-03-14 22:21:58.413641+00', 'Coenzym Q nimmt Elektronen aus Komplex I und II auf und bringt sie zu Komplex III. Cytochrom c arbeitet erst zwischen Komplex III und IV.'),
	('73eed66c-8291-4257-8bef-347ea2613400', 'Immunologie', 'Welches Zytokin foerdert besonders die Reifung und Aktivierung eosinophiler Granulozyten?', '["Interleukin-5 (IL-5)", "Interleukin-2 (IL-2)", "Interleukin-10 (IL-10)", "Tumornekrosefaktor alpha (TNF-alpha)"]', 'Interleukin-5 (IL-5)', '2026-03-14 22:03:54.627029+00', 'immunologie-il5-eosinophile', '2026-03-14 22:21:58.413641+00', 'IL-5 ist das Leitzytokin fuer Eosinophile. Es foerdert ihre Differenzierung, Aktivierung und ihr Ueberleben und spielt daher bei Parasitosen und allergischen Erkrankungen eine wichtige Rolle.'),
	('5fffa130-fe7a-4cea-801d-9658f165e9aa', 'Genetik', 'Welcher Karyotyp ist fuer das Turner-Syndrom klassisch?', '["Monosomie X (45,X)", "Trisomie 21 (47,XX,+21 oder 47,XY,+21)", "Klinefelter-Karyotyp (47,XXY)", "normaler maennlicher Karyotyp (46,XY)"]', 'Monosomie X (45,X)', '2026-03-14 22:03:54.627029+00', 'genetik-turner-45x', '2026-03-14 22:21:58.413641+00', 'Das Turner-Syndrom ist klassisch mit einer Monosomie X assoziiert, also 45,X. Die fehlende zweite Geschlechtschromosomenkopie erklaert viele der typischen klinischen Befunde.'),
	('3198cd09-826d-4617-8230-77a5aea57c23', 'Genetik', 'Welche Trinukleotidsequenz ist im HTT-Gen bei Morbus Huntington pathologisch expandiert?', '["CAG-Repeat", "CGG-Repeat", "CTG-Repeat", "GAA-Repeat"]', 'CAG-Repeat', '2026-03-14 22:03:54.627029+00', 'genetik-huntington-cag', '2026-03-14 22:21:58.413641+00', 'Morbus Huntington beruht auf einer CAG-Repeat-Expansion im HTT-Gen. Die Zahl der Wiederholungen korreliert mit Antizipation und oft mit einem frueheren Krankheitsbeginn in nachfolgenden Generationen.'),
	('9dfc6ea0-bb64-4c8c-9a7d-f643d5595f3c', 'Chirurgie', 'Welche sofortige medikamentoese Massnahme gehoert zur Initialtherapie einer akuten arteriellen Gliedmassenischaemie vor der Revaskularisation?', '["sofortige systemische Heparinisierung", "hochdosiertes Insulin", "langsame Eiseninfusion", "nur orale Analgesie"]', 'sofortige systemische Heparinisierung', '2026-03-14 22:03:54.720926+00', 'chirurgie-akute-gliedmassenischaemie-heparin', '2026-03-14 22:21:58.413641+00', 'Bei akuter arterieller Gliedmassenischaemie wird frueh systemisch heparinisiert, um eine weitere Thrombuspropagation zu verhindern. Diese Massnahme verknuepft die Notfallsituation direkt mit der Initialtherapie.'),
	('365d6b99-d12c-4007-bcd4-792f53f206b8', 'Pharmakologie', 'Was ist ein typisches Zeichen einer Hyperthyreose?', '["Gewichtszunahme", "Bradykardie", "Tachykardie", "Hypotonie"]', 'Tachykardie', '2025-10-31 12:10:03.227174+00', 'mittel-12', '2026-03-14 13:27:23.944128+00', 'Tachykardie ist ein typisches Zeichen der Hyperthyreose, weil Schilddruesenhormone die Empfindlichkeit fuer Katecholamine steigern. Dadurch schlagen Herz und Kreislauf schneller.'),
	('0c4ed9b6-7d3f-4a98-b402-c565f29d9118', 'Anatomie', 'Welche Diagnostik ist Goldstandard zur Bestaetigung einer Lungenembolie?', '["Ventilations-Perfusions-Szintigrafie", "CT-Angiografie", "Thoraxroentgen", "Sonografie"]', 'CT-Angiografie', '2025-10-31 12:10:03.227174+00', 'schwer-13', '2026-03-14 13:27:23.944128+00', 'Die CT-Angiografie ist bei stabilen Patientinnen und Patienten der Standard zur Sicherung einer Lungenembolie. Sie kann Fuellungsdefekte in den Pulmonalarterien direkt darstellen.'),
	('42894931-a571-4605-8b37-46aaf1ce5d77', 'Mikrobiologie', 'Welche Einheit wird zur Messung des Blutdrucks verwendet?', '["Millimeter Quecksilber", "Milligramm", "Liter", "Volt"]', 'Millimeter Quecksilber', '2025-10-31 12:10:03.227174+00', 'leicht-13', '2026-03-14 13:27:23.944128+00', 'Der Blutdruck wird klassisch in Millimeter Quecksilber gemessen, abgekuerzt mmHg. Die Einheit geht auf die Hoehe einer Quecksilbersaeule im Messgeraet zurueck.'),
	('73e509f8-c1ae-47fe-8b55-1be668f1c311', 'Immunologie', 'Welche Struktur ist beim Guillain-Barre-Syndrom primaer betroffen?', '["Motoneuron im Vorderhorn", "Myelinscheide peripherer Nerven", "Rinde des Grosshirns", "Basalganglien"]', 'Myelinscheide peripherer Nerven', '2025-10-31 12:10:03.227174+00', 'schwer-2', '2026-03-14 13:27:23.944128+00', 'Beim Guillain-Barre-Syndrom richtet sich die Immunreaktion gegen die Myelinscheide peripherer Nerven. Das fuehrt zu aufsteigender schlaffer Laehmung und Areflexie.'),
	('0ec6c1b0-bab2-4ac2-bde4-cbd18587d33e', 'Physiologie', 'Welcher Blutwert zeigt eine moegliche Anemie an?', '["Hoher Haemoglobinwert", "Niedriger Haemoglobinwert", "Hoher Cholesterinwert", "Niedriger CRP-Wert"]', 'Niedriger Haemoglobinwert', '2025-10-31 12:10:03.227174+00', 'mittel-5', '2026-03-14 13:27:23.944128+00', 'Ein niedriger Haemoglobinwert spricht fuer eine moegliche Anaemie, weil Haemoglobin den Sauerstofftransport der Erythrozyten bestimmt.');
